		local EC_START = { 0, 20, 40, 60, 80, 100, 121 }
		local EC_COUNT = { 20, 20, 20, 20, 20, 21, 2 }
		local function ec_word(id)
			if id == 0xFFFF then return nil end        -- the game's own "no word" sentinel
