	-- more, exactly like every other door. But sliding from the summit to the bottom is an ARRIVAL he
	-- asked to hear, and silence on the longest ride in the mountain would be the worse failure.
	ow.vr = {}
	function ow.vr.step()
		local z = reg.zid()
		if not ow.RAILISLE[z] then ow.vr.fl = nil; return end
		local c = rail.sys(); if not (c and ow.isle_certified(c, z)) then return end
		local isl = rail.isle_now(c); if not isl then return end
		if ow.pend then return end                                      -- the place name goes first
		local f = ow.ISLE_FLOOR[z] and ow.ISLE_FLOOR[z][isl]; if not f then return end
		if ow.vr.fl == f then return end
		local first = (ow.vr.fl == nil)
		ow.vr.fl = f
		if first and f == 1 then return end                             -- see the no-1F note above
		say(f .. "F", not first)
	end
	-- Zones where ow.reg_aim may fall back to the nearest accepted doorway tile — see the long note at
