		local i = 0; for x in (GROWTH_ .. ","):gmatch("(.-),") do GROWTH[i] = tonumber(x); i = i + 1 end
		local g = 0
		for tab in (EXPTAB_ .. "|"):gmatch("(.-)|") do
			local t, L = {}, 0
			for v in tab:gmatch("%d+") do t[L] = tonumber(v); L = L + 1 end
			if L > 0 then EXPTAB[g] = t; g = g + 1 end
