	local function level_from_exp(species, xp)
		local t = EXPTAB[GROWTH[species] or 0]
		if not (t and xp) then return nil end
		for L = 100, 1, -1 do if t[L] and xp >= t[L] then return L end end
		return 1
	end
	-- The same curves the other way round, for the SUMMARY screen's "To Next Lv." — which the game
	-- computes as expAtLevel(species, level + 1) - currentExp, and shows 0 at level 100
	-- (ov131 FUN_021d7f24: two FUN_020185a0 calls with level+1 and level, `if (lv == 100) diff = 0`).
	reg.exp_for_level = function(species, lv)
		local t = EXPTAB[GROWTH[species] or 0]
		return (t and lv and lv >= 0 and lv <= 100) and t[lv] or nil
	end
	-- ⛔ THE PARTY TEST IS `box == 0xFF OR slot > 0x1D`, NOT just the slot (Ola 2026-08-06: in Move mode the
	-- party members all read "empty"). This is a straight transcription of the game's own slot resolver
	-- FUN_021DD2F0: `if ((box == 0xff) || (0x1d < slot)) { if (0x1d < slot) slot -= 0x1e; <party> }`.
	-- On the Move screen the cursor sits on the party with **box = 0xFF and slot 0..5** — and the subtraction
	-- only applies in the OTHER case. Testing the slot alone sent those through the box path with box 255,
	-- which computes an address far outside the save and reads as empty.
	local function party_index(b, slot)
		if b ~= 0xFF and slot <= 0x1D then return nil end
		return (slot > 0x1D) and (slot - 0x1E) or slot
	end
	local function mon_addr(w, b, slot)
		local pi = party_index(b, slot)
		if pi then
			local party = u32(u32(w) + 0x08)                                  -- ProcData+0x08 = Party
			return inram(party) and (party + 8 + pi * 0xDC) or nil
		end
		local ls = live_save(w); if not ls then return nil end
		return ls + 0x400 + b * 0x1000 + slot * 0x88                          -- stride 0x1000, not 0xFF0
	end
	-- The name of what is under the cursor, and its mon record (nil, nil when there is nothing to read;
	-- "empty" with no record for a free slot). Nickname wins over the species name, as the screen shows.
	local function cursor_mon(w, b, slot)
		if slot == 0xFF then return nil end
		local read = reg.mon_read; if not read then return nil end
		local addr = mon_addr(w, b, slot); if not addr then return nil end
		-- A party record is the full one; a grid slot is a 0x88 BOX record and must be read core-only,
		-- or the next slot's bytes get decrypted as its stats and it reads as empty.
		local m = read(addr, party_index(b, slot) == nil)
		if not m then return "empty" end
		if m.isegg then return "Egg" end
		local sp = reg.spname
		return (m.nick ~= "" and m.nick) or (sp and sp(m.species)) or ("species " .. m.species), m
	end
	-- Everything the on-screen panel shows, after the name and position (Ola Q1 "all of it, important
	-- stuff first"; Q6 "match what sighted people see"). Any field we cannot name is simply omitted —
	-- silence beats a wrong word. All the lookup tables come through the registry because this module is
	-- registered ABOVE where they are declared (the load-order trap that would have made every Pokémon
	-- read as "species 522").
	local function details(m)
		local out = {}
		-- Box records carry no level (it lives in the party extension); say it only when we really have it.
		local lv = m.level or level_from_exp(m.species, m.exp)   -- box records: derived from EXP
		if lv then out[#out + 1] = "level " .. lv end
		local ty, tn = SPTYPES[m.species], reg.type_names
		if ty and tn and tn[ty[1]] then
			out[#out + 1] = (ty[1] == ty[2]) and tn[ty[1]] or (tn[ty[1]] .. " " .. tn[ty[2]])
		end
		if NATURES[m.nature] then out[#out + 1] = NATURES[m.nature] .. " nature" end
		-- ability 0 is the game's own "--" placeholder; say nothing rather than read punctuation aloud
		if m.ability and m.ability > 0 and ABILITIES[m.ability] then out[#out + 1] = ABILITIES[m.ability] end
		local items = reg.items
		local held = (m.item and m.item ~= 0 and items) and items[m.item] or nil
		out[#out + 1] = held and ("holding " .. held) or "no item"
		local mv, mvname = {}, reg.mvname
		for i = 1, 4 do
			local id = m.moves[i]
			if id and id ~= 0 then mv[#mv + 1] = (mvname and mvname(id)) or ("move " .. id) end
		end
		if #mv > 0 then out[#out + 1] = table.concat(mv, ", ") end
		return out
	end
	-- How many Pokémon are in a box — the game computes this too (FUN_020078C4 walks all 30 records), so
	-- we walk them the same way. Only ever called when the box CHANGES, and mon_read caches per address.
	local function box_count(w, b)
		local ls, read = live_save(w), reg.mon_read
		if not (ls and read) then return nil end
		local n = 0
		for s = 0, 29 do
			if read(ls + 0x400 + b * 0x1000 + s * 0x88, true) then n = n + 1 end
		end
		return n
	end
	local function where(b, slot)
		local pi = party_index(b, slot)
		if pi then return nil, nil, "party " .. (pi + 1) end
		return math.floor(slot / 6) + 1, (slot % 6) + 1, nil
	end
	-- ⛔ WHEN THE GRID IS ACTUALLY INTERACTIVE, AND WHERE THE LIVE CURSOR IS (Ola 2026-08-05: it spoke
	-- "Box 1" while the box was still animating in, and then did not speak at all as he moved).
	-- Both answers come from the app's OWN browse handlers, and the same idiom appears in two independent
	-- ones (state 0x14 FUN_021E2BA8 and state 0x1F FUN_021E3CA8), so it is the app's rule and not a guess:
	--   ui = u32(work + 0x2C)  — the screen object.
	--   **u32(ui + 0xA194) is a STEP counter, and each handler refuses to act until it is 2**
	--   (`if (step != 2) return <same state>;` — literally does nothing while the screen animates in).
	--   Gating our speech on the same test is exactly what the game does before it will read the cursor,
	--   which is the standing SUBMENUS rule: gate on the widget's own accepting-input state.
	--   **The LIVE cursor is the list widget's, not work+0x16.** The browse handler seeds work+0x16 from
	--   `FUN_020260FC(u32(ui + 0x70))` during setup and re-reads it only when it acts, so work+0x16 is a
	--   SNAPSHOT — reading it is why moving around said nothing. FUN_020260FC decompiles to
	--   `return u8(param + 0x0D)`, the live index of the shared list library the battle party list already
	--   uses (white.lua: the d-pad writes +0x0D directly).
	-- ⛔⛔ THE REAL MODEL, from the full Ghidra map of ov170's 105 states (Codex front, 2026-08-06;
	-- research/re/ov170_state_machine_report.md). My three earlier attempts were all wrong in the same way:
	-- I treated the screen as "one grid with one cursor". It is not.
	--   * **state = u32(proc + 0x0C)** decides everything. Only 21 of the 105 states accept input at all.
	--   * **ONE list widget serves box AND party**: list = u32(ui + 0x70), live index = u8(list + 0x0D).
	--     Box browse uses 0..29. Party browse uses **0..5** — consumers add 0x1E when resolving the mon
	--     (verified: Deposit's own handler FUN_021E559C does `FUN_021DD27C(work, idx + 0x1e, box, ...)`).
	--   * **The action menu lives in the SAME state as the browse it came from**, as list indices **8..12**.
	--     That is exactly why pressing A spoke "empty, row 2, column 3" at Ola: index 8 was being read as
	--     box slot 8.
	--   * ⛔ `ui+0xA194 == 2` IS NOT AN INPUT PREDICATE — it is the pickup sub-step counter used only by
	--     states 0x14/0x1F, reset immediately. Gating on it is why the reader went silent altogether.
	--   * Carrying a Pokémon is **u8(work + 0x18) == 1** (set by FUN_021EA134/FUN_021EA0DC, cleared by
	--     FUN_021EA534) — NOT the selection nibble at work+0x1C.
	local INTERACTIVE = { [0x06]=1,[0x07]=1,[0x0F]=1,[0x11]=1,[0x15]=1,[0x18]=1,[0x1B]=1,[0x20]=1,[0x23]=1,
	                      [0x27]=1,[0x2C]=1,[0x31]=1,[0x35]=1,[0x39]=1,[0x40]=1,[0x46]=1,[0x4B]=1,[0x56]=1,
	                      [0x5E]=1,[0x61]=1,[0x65]=1 }
	local BOX_BROWSE   = { [0x11]=1,[0x23]=1,[0x2C]=1,[0x35]=1,[0x39]=1,[0x4B]=1,[0x15]=1 }   -- 0x15 = carrying
	local PARTY_BROWSE = { [0x1B]=1,[0x27]=1,[0x31]=1,[0x46]=1,[0x20]=1 }                      -- 0x20 = carrying
	local CARRY_STATE  = { [0x15]=1,[0x20]=1 }   -- the Move Pokemon carry flow, the only real "holding"
	-- Action-menu row labels. The row tables live in the overlay as {u16 textId, u16 lastFlag} runs (bit 0 of
	-- the flag marks the final row) and the words come from a/0/0/2 bank 9 — both read out of the ROM, so
	-- these are the game's own labels. Deposit's table at 0x021EF970 is the one Codex proved and I re-checked.
	-- state -> its action-menu row table, found by scanning each browse handler's own literal pool for a
	-- pointer into the table region and confirmed by resolving every row through bank 9. The method
	-- validates itself: it independently reproduced 0x021EF970 for Deposit, the one address Codex had
	-- already proven from the code. States 0x11/0x1B/0x39/0x46 load their tables elsewhere and are NOT
	-- mapped yet, so those menus stay silent rather than guessing.
	-- state -> the list index of the menu's FIRST row, taken from that state's own switch statement.
	-- state -> list index of the menu's FIRST row, from each handler's own switch: the cases calling
	-- the action helper FUN_021E94BC form a contiguous run and its lowest command is row 0. (Those
	-- action NUMBERS are action codes, not row indices — 0x23's rows are actions 2..5 and another of
	-- its cases uses action 10 — so the run's base is what matters.) Each base is checked against its
	-- table's row count: 0x23/0x27 have 4 rows, 0x2C/0x31 have 5, 0x4B has 2.
	local MENU_BASE  = { [0x11] = 0x24, [0x1B] = 0x09, [0x23] = 0x24, [0x27] = 0x09,
	                     [0x2C] = 0x23, [0x31] = 0x08, [0x4B] = 0x22, [0x5E] = 0x00 }
	local BOX_HEADER = { [0x11] = 1, [0x23] = 1, [0x2C] = 1 }   -- 0x1E/0x1F/0x20 read off each switch
	local MENU_TABLE = {
		[0x23] = 0x021EF938, [0x27] = 0x021EF938,   -- MOVE / SUMMARY / HELD ITEMS / CANCEL
		[0x2C] = 0x021EF9D4,                        -- WITHDRAW / SUMMARY / MARKING / RELEASE / CANCEL
		[0x31] = 0x021EF970,                        -- DEPOSIT  / SUMMARY / MARKING / RELEASE / CANCEL
		[0x4B] = 0x021EF90C,                        -- TUCK IN / CANCEL
		-- ⛔ MOVE POKEMON is 0x11/0x1B, NOT 0x23/0x27, and its table has SIX rows. I wired the
		-- four-row 0x021EF938 as "Move" and Ola got a silent menu: his screenshot shows MOVE /
		-- SUMMARY / HELD ITEMS / MARKING / RELEASE / CANCEL. Two things had hidden it — my
		-- per-state table scan stopped at 0x021EFA10, just short of this table, and bank 9 has
		-- TWO 'MOVE' entries so searching for the wrong id found nothing.
		[0x11] = 0x021EFA30, [0x1B] = 0x021EFA30,   -- MOVE/SUMMARY/HELD ITEMS/MARKING/RELEASE/CANCEL
		-- The BOX HEADER menu — what you get by going up to the box name and pressing A. Its table
		-- pointer lives in the SETUP state (0x5D), not in the menu state itself, which is why my
		-- per-state scan kept coming back empty for it.
		[0x5E] = 0x021EF928,                        -- SWITCH BOX / WALLPAPER / NAME / CANCEL
	}
	-- The WHOLE of a/0/0/2 bank 9, baked by research/re/extract_text.py — every word these menus can
	-- show, so a newly-mapped table resolves without me hand-adding ids one at a time (I did that four
	-- times and it is how "Move" got the wrong id). Sentence-cased for speech; the screen draws capitals.
	-- ⚠ The charcodes are Unicode-aligned, not ASCII: 0x00C9 is E-acute (POKÉ CENTER) and the 0x24xx
	-- range is private glyph ICONS with no spoken form, which are dropped rather than read as "?".
	local MENU_WORD = {}
	do
		local w = "ā,Ă,,,,,Box 1,Box 2,Box 3,Box 4,Box 5,Box 6,Box 7,Box 8,Box 9,Box 10,Box 11,Box 12,Box 13,Box 14,Box 15,Box 16,Box 17,Box 18,Box 19,Box 20,Box 21,Box 22,Box 23,Box 24,ȁ,Switch box,Wallpaper,Name,Cancel,Scenery 1,Scenery 2,Scenery 3,Misc.,,,Forest,City,Desert,Savanna,Crag,Volcano,Snow,Cave,Beach,Seafloor,River,Sky,Poké center,Machine,Checks,Simple,Special,Reshiram,Zekrom,Monochrome,Team plasma,Munna,Zoroark,Subway,Musical,Back,Previous,Next,Party,Box list,Battle box,,,Summary,Held items,Marking,Release,Withdraw,Deposit,Cancel,Move,Move,Tuck in,Confirm,Cancel,,,,,,,Bag,Give,Move,,,Ć,Ĉ,ĉ,Nature,Ability,Item,Ȃ,Ȃ,None,???,Lv.,No.,Moves learned,Yes,No"
		local i = 0; for x in (w .. ","):gmatch("(.-),") do MENU_WORD[i] = x; i = i + 1 end
	end
	local function menu_rows_for(state)
		local base = MENU_TABLE[state]; if not base then return nil end
		base = base + DELTA
		local rows = {}
		for i = 0, 9 do
			local tid, flag = u16(base + i * 4), u16(base + i * 4 + 2)
			rows[#rows + 1] = MENU_WORD[tid] or ("option " .. (i + 1))
			if (flag & 1) == 1 then break end
		end
		return rows
	end
	-- What the screen is showing right now: kind ("box" | "party" | "menu"), the index, and the row list
	-- for a menu. nil when the state does not accept input — then we say nothing at all.
	local function box_view(w, proc)
		local state = u32(proc + 0x0C)
		if not INTERACTIVE[state] then return nil end
		local ui = u32(w + 0x2C);     if not inram(ui) then return nil end
		local list = u32(ui + 0x70);  if not inram(list) then return nil end
		local idx = u8(list + 0x0D)
		if idx == 0xFF then return nil end
		-- ⛔ THE ACTION-MENU INDEX BASE IS PER STATE, not a universal 8. Deposit's rows are list indices
		-- 8..12, but Withdraw's are 0x23..0x27 — read straight out of each handler's own switch, where
		-- the cases call the action helper FUN_021E94BC with the row number. Assuming 8 everywhere is
		-- why Withdraw announced "option 28" (its real index 0x23 minus my wrong base of 8).
		-- Only bases read directly off a handler's switch AND matching their table's row count are wired.
		-- Anything unmapped stays SILENT — a menu we cannot name says nothing rather than a number.
		-- Note the base is checked BEFORE the browse branches, so a pure menu state (the box header, 0x5E)
		-- works without belonging to either browse set.
		local mbase = MENU_BASE[state]
		if mbase and idx >= mbase then
			local rows = menu_rows_for(state)
			if rows and rows[idx - mbase + 1] then return "menu", idx - mbase, rows, state end
			return nil
		end
		-- Above the grid sit the box header and the two box-change arrows. Read from state 0x2C's own
		-- switch: 0x1E jumps to the box-header menu (state 0x5D), 0x1F and 0x20 step the box back and
		-- forth. The arrows are drawn as art with no text behind them, so the two words are ours — the
		-- one case CLAUDE.md allows. The header speaks the box's own name.
		if BOX_BROWSE[state] and idx > 0x1D then
			if BOX_HEADER[state] then
				if idx == 0x1E then return "header", idx, nil, state end
				if idx == 0x1F then return "prevbox", idx, nil, state end
				if idx == 0x20 then return "nextbox", idx, nil, state end
			end
			return nil                                   -- the rest of that row is unmapped: stay silent
		end
		if idx > 5 and PARTY_BROWSE[state] then return nil end
		if PARTY_BROWSE[state] then return "party", idx, nil, state end
		if BOX_BROWSE[state] then return "box", idx, nil, state end
		if state == 0x07 then                            -- confirmation ("Continue Box operations?")
			-- The GRID-MENU-LIB widget, not the list one: state 0x07 drives it with FUN_0202798C and asks
			-- FUN_02027A00 whether a choice has been made. That library is already banked in CLAUDE.md from
			-- three earlier screens: cursor u8(+0x00), item count u8(+0x24), and **u32(+0x0C) == 0 means it
			-- is live and accepting input** — the same +0x0C rule that fixed the party and bag submenus.
			local cw = u32(ui + 0x1A0); if not inram(cw) then return nil end
			if u32(cw + 0x0C) ~= 0 then return nil end     -- decided / closing: stay quiet
			local n = u8(cw + 0x24)
			if n == 0 or n > 8 then return nil end
			-- Row labels are the widget's OWN Strings — no hardcoded words. The row descriptors are copied
			-- to widget+0x1C (0x0C each, StrBuf* first), which FUN_02027A3C dereferences to draw them;
			-- ui+0x184 is the same list in a form that outlives the widget. reg.str_text validates the
			-- StrBuf magic, so an unreadable row yields nil and we simply stay quiet.
			local rows, base = {}, u32(cw + 0x1C)
			for i = 0, n - 1 do
				local t = (inram(base) and reg.str_text(u32(base + i * 0x0C)))
				        or reg.str_text(u32(ui + 0x184 + i * 0x0C))
				if not t then return nil end
				rows[#rows + 1] = t
			end
			return "confirm", u8(cw), rows, state
		end
		if state == 0x40 then                            -- Move Items: one unified 0..0x1D / 0x1E..0x23 space
			if idx <= 0x1D then return "box", idx, nil, state end
			return "party", idx - 0x1E, nil, state
		end
		return nil                                       -- message / choice / wallpaper etc: not ours yet
	end
	-- ⛔ RESTORED. An earlier rewrite of this module deleted this assignment while replacing the block it
	-- sat in, leaving pc_box_active declared, referenced, and permanently nil — so the field-script-menu
	-- stand-down silently did nothing for several rounds. luaundef cannot catch declared-but-never-assigned.
	pc_box_active = function() return box_work() ~= nil end
	local last_b, last_key, last_hold, said_any, last_kind, last_msg
	local MSG_STATE = { [0x06]=1, [0x07]=1, [0x18]=1 }   -- the only states where ui+0x88 is a message
	MODULES[#MODULES + 1] = {
		name = "pc box",
		-- ⛔ STAND DOWN WHILE A SUMMARY PROC EXISTS (2026-09-03, wiring the box-sourced summary). Both
		-- gates read the SAME slot — u32(u32(GameSystem+0x08)+0x08) — so in principle they are already
		-- mutually exclusive by vtable. This guard is the insurance: this module is registered well
		-- before the summary, first match wins, and if the box ever launches the summary on a nested
		-- manager instead (the shape the trainer card uses) the box proc would stay current here and
		-- silently starve it. That is the exact failure the party screens spent August on, and the
		-- predicate to prevent it already exists.
		detect = function()
			if party_proc_active and party_proc_active() then return false end
			return box_work() ~= nil
		end,
		on_enter = function()
			last_b, last_key, last_hold, said_any, last_kind, last_msg = nil, nil, nil, false, nil, nil
		end,
		on_exit = function() pc_box_closed = true end,
		update = function()
			local w, proc = box_work()
			if not w then return end
			local state = u32(proc + 0x0C)
			-- ⛔ THE MESSAGE WINDOW, and it MUST stay state-gated. u32(ui+0x88) is the StrBuf the app expands
			-- its messages into (FUN_021EAC48 -> FUN_0201F26C(formatter, u32(ui+0x88), template); the text
			-- comes from a/0/0/2 bank 10 — [0x00] "??? is selected.", [0x02] "Release this Pokemon?",
			-- [0x05] "Your party's full!", [0x0B] "Continue Box operations?", all verified by extracting the
			-- bank). Outside the message states that same StrBuf is SHARED SCRATCH, which is the trap the bag
			-- screen taught us on 2026-08-04 — read it anywhere else and it narrates whatever last passed
			-- through. So: only states 0x06, 0x07 and 0x18. It INTERRUPTS (Ola: the question is the point), and
			-- the option that follows QUEUES behind it — see the say() at the end of this handler.
			local spoke_msg = false
			local uio = u32(w + 0x2C)
			if MSG_STATE[state] and inram(uio) then
				local t = reg.str_text(u32(uio + 0x88), 4096)
				if t and t ~= last_msg then last_msg = t; said_any = true; spoke_msg = true; say(t, true) end
			else
				last_msg = nil
			end
			local kind, idx, rows, state2 = box_view(w, proc)
			state = state2 or state
			if not kind then return end                        -- not accepting input: say nothing
			local b = u8(w + 0x14)
			local key = kind .. ":" .. idx .. ":" .. b
			-- Ola Q5 = B: announce the pick-up ONCE, then read slots normally.
			-- ⛔ ONLY IN THE ACTUAL CARRY STATES. u8(work+0x18) is also set for Deposit's "carry it to a
			-- box" step, so keying purely on the flag announced "picked up" the moment Ola chose DEPOSIT —
			-- where he is only being asked which box to put it in (state 0x35, the destination selector).
			-- Codex's map says the same thing: a physically carried Pokemon is the flag AND the 0x15/0x20
			-- carry flow, and those states can also run with the flag clear for selection modes.
			local holding = (u8(w + 0x18) == 1)
			local pick = (holding and not last_hold and CARRY_STATE[state] ~= nil)
			last_hold = holding
			if key == last_key and not pick then return end
			-- ⛔ INTERRUPT unless this is the FIRST thing said since entering the screen. This must be a
			-- visit-scoped flag: it used to be `last_key == nil`, and since a single non-interactive frame
			-- cleared last_key, nearly every announcement looked like a first landing and QUEUED instead
			-- of interrupting — which is exactly what Ola heard opening the menu and moving the cursor.
			local first = not said_any
			said_any = true
			local newbox = (b ~= last_b)
			local prev_kind = last_kind          -- capture BEFORE overwriting; the box-name test needs it
			last_key, last_b, last_kind = key, b, kind
			local bits = {}
			if pick then bits[#bits + 1] = "picked up" end
			if kind == "header" then
				bits[#bits + 1] = box_name(w, b) or ("Box " .. (b + 1))
			elseif kind == "prevbox" or kind == "nextbox" then
				bits[#bits + 1] = (kind == "prevbox") and "previous box" or "next box"
			elseif kind == "confirm" or kind == "menu" then
				bits[#bits + 1] = rows[idx + 1]
				bits[#bits + 1] = (idx + 1) .. " of " .. #rows
			else
				local slot = (kind == "party") and (idx + 0x1E) or idx
				-- Say the box name when the box CHANGES or when we first arrive on a box-side screen. It used
				-- to key on `first` alone, which is set once per visit to the whole PC — so stepping from the
				-- party into the deposit destination selector announced no box at all, and only spoke it once
				-- Ola moved far enough to change box (Ola 2026-08-06).
				if kind == "box" and (newbox or first or prev_kind ~= "box") then
					local nm = box_name(w, b) or ("Box " .. (b + 1))
					local n = box_count(w, b)
					bits[#bits + 1] = n and (nm .. ", " .. n .. " Pokemon") or nm
				end
				local what, m = cursor_mon(w, b, slot)
				bits[#bits + 1] = what or "empty"
				if kind == "party" then
					bits[#bits + 1] = "party " .. (idx + 1)
				elseif state ~= 0x35 then
					-- Not on the deposit DESTINATION selector: there you are only choosing where to put the
					-- Pokemon, and Ola asked for the grid position to stay out of it (2026-08-06).
					bits[#bits + 1] = "row " .. (math.floor(idx / 6) + 1)
					bits[#bits + 1] = "column " .. ((idx % 6) + 1)
				end
				if m then for _, d in ipairs(details(m)) do bits[#bits + 1] = d end end
			end
			-- ⛔ QUEUE BEHIND A MESSAGE WE JUST SPOKE. This is why "Continue Box operations?" and "Release
			-- this Pokemon?" were silent while their Yes/No spoke (Ola 2026-08-06): the message queued, then
			-- the option announcement in the SAME frame counted as "not the first thing said" and
			-- INTERRUPTED it — cutting the question off before a word of it was heard. Codex's chain was
			-- right all along; the bug was the interrupt rule I added two rounds earlier.
			say(table.concat(bits, ", "), not first and not spoke_msg)
		end,
	}
end

;(function()
	-- ===== 1e2) THE EVOLUTION SCREEN (ov195 "shinka_demo") — nothing here spoke (Ola, 2026-09-03) =====
	-- The whole screen: "What? Servine is evolving!", "Huh? Servine stopped evolving!" (B cancels it),
	-- "Congratulations! Your Servine evolved into Serperior!", and then the move-learning that follows an
	-- evolution — "… wants to learn the move X. However, … already knows four moves. Should a move be
	-- deleted and replaced with X?" with its two big buttons FORGET / KEEP OLD MOVES!.
	-- RE 2026-09-03 (Claude, canonical Ghidra project; ov195 remapped over 0x02203FC0):
	-- ▶ IT IS FIELD APP 10 in ov010's app registry (base 0x021712EC, stride 0x18, record
	--   {ovId, vtable, buildProcData, returnHandler, 0, common}): entry 10 = { 195, 0x02208C60,
	--   0x02161575, 0x02161631 } — the same registry the party list (entry 0), summary (entry 6) and the
	--   town map (entry 7) already come from. So it is an ordinary GameProc and needs NO new machinery:
	--   proc_with_vt finds it exactly as it finds the party screen.
	--     vtable **0x02208C60** = {Init 0x02203FC0, Main 0x02204100, End 0x022040B8}
	--   ⚠ BLACK IS MEASURED, NOT ASSUMED (the ov88 lesson): ov195's base moves 0x02203FC0 -> 0x02203FA0
	--   (a clean -0x20, same 0x5000 size, 95.8% of bytes identical — not a rebuilt overlay), and the
	--   vtable sits at the SAME file offset +0x04CA0 in both ROMs holding exactly White-0x20. The
	--   fn-ptr-spacing search over the whole Black overlay finds that triple ONCE, at that offset. So
	--   plain DELTA is correct here and no special constant is needed.
	-- ▶ THE SUBSYSTEM (proc+0x14), 0x120 bytes, heap id 0x94, memset to 0 by Init (FUN_02203FC0):
	--     +0x00 u16 heap id (0x94)              +0x10 the Pokemon (Party_GetMonBySlot from the ProcData)
	--     +0x14 a String, capacity 0x100        +0x28 THE STATE (46-way jump table at 0x02204132)
	--     +0x64 the live TextPrinter            +0x6C the message window   +0x78 bank 172 handle
	--     +0x7C bank 204 handle                 +0x80 THE MESSAGE String   +0x90 bank 233 handle
	--     +0x94 button 1 String  +0x98 button 2 String  +0x9C the ov067 yesno_menu
	--     +0x11C its OWN child GameProcManager
	-- ▶ THE MESSAGE. FUN_022053A4(sub, bankHandle, msgId, speed, kind0, arg0, kind1, arg1) builds the
	--   finished, localized, slots-already-filled sentence through FUN_02205640 (String_Init(0x100) +
	--   StringTemplate expand) and stores it at **sub+0x80**, then hands it to Text_AddPrinter
	--   (0x0201CD2C) and keeps the printer at **sub+0x64**. So ONE read of sub+0x80 gives the whole
	--   sentence in the game's own words — no id table, no hardcoded English, and it works on both ROMs.
	--   The banks it prints from are its own: 172 (0 "What? {} is evolving!", 1 "Huh? {} stopped
	--   evolving!", 2 "Congratulations! Your {} evolved into {}!") and 204 (3 "{} learned {}!",
	--   4 the four-moves question, 5 "1, 2, and… Ta-da! {} forgot how to use {}. And…", 6, 7, 8).
	--   Init memsets the object, so before the first print sub+0x80 is 0 and reg.str_text fails closed.
	-- ▶ THE TWO BUTTONS. State 0x15 builds them with FUN_022055DC(sub, bank233, 2, …, bank233, 3, …),
	--   which calls FUN_02205640 twice and stores the two finished Strings at **sub+0x94** (bank 233[2] =
	--   "FORGET") and **sub+0x98** (bank 233[3] = "KEEP OLD MOVES!"), then opens the widget with
	--   FUN_021B7114(menu, sub+0x94, sub+0x98). We read the row's OWN String — no id mapping, so if this
	--   widget is ever opened with different words we say the game's words, not ours.
	-- ▶ THE WIDGET IS ov067's **yesno_menu.c** (White base 0x021B6120, Black 0x021B6100 = -0x20,
	--   MEASURED), the shared two-button library — create FUN_021B6DE0 (0xCC bytes, allocator tag
	--   "yesno_menu.c"), start FUN_021B7114, per-frame FUN_021B7398, poll FUN_021B76D0, close
	--   FUN_021B72FC. Its fields, read out of FUN_021B7398 instruction by instruction:
	--     **+0x98 = the phase** — the poll is literally
	--        `if (menu+0x98 != 0 && menu+0x98 != 4) return 2; return menu+0x9C;`
	--       and the per-frame handler only reads the D-pad in **phase 2**. So phase 2 IS the game's own
	--       "this widget is accepting input" predicate — the SUBMENU hard rule's flag, not a guess about
	--       animation. Phase 3 is the close animation, 4/0 done.
	--     **+0xC0 = the cursor**: `keys & 0x40` (UP) sets it to 0, `keys & 0x80` (DOWN) sets it to 1, and
	--       the two windows are created at y=5 (upper, from FUN_021B7114's first String) and y=0x0B
	--       (lower, the second). So 0 = the FIRST label (sub+0x94), 1 = the SECOND (sub+0x98).
	--     +0x9C = the result the poll returns once the phase leaves 2 (state 0x16 branches on it).
	-- ▶ THE MOVE-TO-FORGET LIST IS NOT OURS TO BUILD. State 0x17 fills a 0x28-byte ProcData at sub+0x100
	--   — +0x00 Party, +0x08 GameData, +0x0D **mode 2**, +0x0F slot, +0x10 start page 1, **+0x14 the
	--   incoming move id** — and launches it on the child manager at sub+0x11C. That is EXACTLY the ov131
	--   summary in forget mode, which the summary module already reads in full (rows 0..3 from the mon,
	--   row 4 from ProcData+0x14, count from the page widget). The one thing missing was that the child
	--   runs on a manager of the evolution demo's own, which proc_with_vt could not see — the same shape
	--   as the PC box, and fixed the same way, with reg.evo_child_proc below.
	--   (The other branch, state 0x1B, hands an ov198 struct to FUN_0220F408 instead — the b_plist
	--   move-forget screen. Noted here so it is not re-discovered; it is not wired yet.)
	local EVO_VT = 0x02208C60 + DELTA                                     -- Black 0x02208C40 (MEASURED)
	local YNTAG = { 0x79,0x65,0x73,0x6E,0x6F,0x5F,0x6D,0x65,0x6E,0x75,0x2E,0x63 }   -- "yesno_menu.c"
	-- The demo's subsystem while it is the running proc, else nil. Every hop is revalidated each frame —
	-- vtable identity, RUN status and the heap id Init writes — so a freed or reused proc goes silent.
	-- ⛔ THIS DOES ITS OWN TWO-MANAGER WALK RATHER THAN CALLING proc_with_vt, AND IT MUST. proc_with_vt
	-- now asks every registered child-manager hook, and reg.evo_child_proc below is one of them — so
	-- routing this through it would be proc_with_vt -> evo_child_proc -> evo_sub -> proc_with_vt, an
	-- unbounded recursion that overflows the stack and kills the WHOLE script (and a dead script looks
	-- exactly like a mis-gated reader, which is the most expensive kind of bug this project has).
	-- The walk is correct as well as necessary: the evolution demo is a TOP-LEVEL field app launched by
	-- ov010's registry onto the GameSystem's own sub-manager, so it never lives under another app's
	-- private manager and the two checks below are all there are.
	local function evo_sub()
		local cp = cur_proc()
		if not (cp and u32(cp) == EVO_VT) then
			local gs = u32(GAMESYS_PTR); if not inram(gs) then return nil end
			local mgr = u32(gs + 0x08); if not inram(mgr) then return nil end
			cp = u32(mgr + 0x08)
			if not (inram(cp) and u32(cp) == EVO_VT) then return nil end
		end
		if u32(cp + 0x08) ~= 2 then return nil end                        -- ProcessStatus RUN
		local sub = u32(cp + 0x14); if not inram(sub) then return nil end
		if u16(sub) ~= 0x94 then return nil end                           -- the demo's own heap id
		return sub
	end
	-- Published for proc_with_vt, exactly like the PC box's: the summary opened from here is the current
	-- proc of a manager nothing else looks at, so without this the forget screen would be unreadable.
	reg.evo_child_proc = function()
		local sub = evo_sub(); if not sub then return nil end
		local m = u32(sub + 0x11C); if not inram(m) then return nil end
		local cp = u32(m + 0x08)
		return inram(cp) and cp or nil
	end
	-- ⛔ AND THE TWO GLOBAL FIELD READERS MUST STAND DOWN WHILE THIS SCREEN LIVES — the same stand-down
	-- the shop, the Xtransceiver, the post-catch Pokédex and the naming keyboard all needed. This screen
	-- prints through its OWN private task manager (u32(sub+0x68), created by FUN_02031034 in
	-- FUN_0220521C, exactly as b_plist does), so dialogue_step's four-manager scan cannot see its printer
	-- — which also means instant_msg_step never defers to it, and instant_msg_step reads the FIELD
	-- message holder, which still holds whatever the script said before the Pokémon began evolving.
	-- Deliberately NOT gated on evo_child: the stand-down must cover the whole visit, forget screen
	-- included, because the field holder is just as stale there.
	reg.evo_active = function() return evo_sub() ~= nil end
	-- Is a child app (the forget screen) running on top of us? While one is, this module stands down so
	-- the summary module gets the context — the module-priority starvation the party screen taught us.
	local function evo_child()
		local f = reg.evo_child_proc
		return f and f() or nil
	end
	local msg_last, msg_pages, msg_pi, msg_wait, btn_last
	MODULES[#MODULES + 1] = {
		name = "evolution",
		detect = function() return evo_sub() ~= nil and evo_child() == nil end,
		-- ⛔ RE-ARM ONLY WHEN THE DEMO IS ACTUALLY GONE, NOT WHEN A CHILD TAKES THE CONTEXT. Losing the
		-- context to the forget screen is not leaving this screen: sub+0x80 still holds the question you
		-- just answered, so a reset in on_enter would announce "…Should a move be deleted and replaced
		-- with Hex?" all over again the moment the summary closed. on_exit asks whether the proc itself
		-- has died; only then does the next visit start fresh.
		on_exit = function()
			if evo_sub() == nil then msg_last, msg_pages, msg_pi, msg_wait, btn_last = nil, nil, nil, nil, nil end
		end,
		update = function()
			local sub = evo_sub(); if not sub then return end
			-- THE MESSAGE. Dedup by text, and re-arm whenever the String is unreadable (freed between
			-- messages, or mid-rebuild) so the same sentence appearing again later still speaks — the
			-- party screen's message reader has worked this way for a month.
			-- ⛔ MESSAGES INTERRUPT. Each one is the game's answer to the button you just pressed, and the
			-- first is the first thing said on a new screen. Only the buttons queue, behind their question.
			-- ⛔⛔ AND THEY ARE SPOKEN PAGE BY PAGE (Ola, in game 2026-09-04: "make sure we are using the
			-- page break correctly, right now all of this is in one message, and that is completely wrong").
			-- He is right: a/0/0/2 bank 204[4] is THREE boxes, not one sentence —
			--   "{} wants to learn the move {}." | "However, {} already knows four moves." |
			--   "Should a move be deleted and replaced with {}?"
			-- separated by the F000 BE01 page break, and 204[5] ("1, 2, and… Ta-da!" / "{} forgot how to
			-- use {}." / "And…") is three more. Reading the String whole ran them together into one
			-- run-on utterance that also arrived long before the game had shown any of it.
			-- This screen can do better than the battle reader, which speaks all pages at once because it
			-- only ever sees a finished StrBuf: ov195 prints through a REAL TextPrinter at sub+0x64 — the
			-- same 0x0201CD2C object the party screen's msgwin+0x0C is — and that printer PARKS at each
			-- break waiting for A. So each page is spoken when the game actually puts it up.
			local str = u32(sub + 0x80)
			local t = reg.str_text(str)                                   -- the project's standard 600-char bound
			if not t then
				msg_last, msg_pages = nil, nil
			elseif t ~= msg_last then
				msg_last = t
				-- BE01 ONLY. BE00 is a scroll WITHIN one box, and the advance below counts resume-action 1,
				-- which is BE01's; splitting on both would make more pages than presses and desynchronise
				-- the cursor. That exact regression was found and reverted on the party screen.
				msg_pages = reg.str_pages(str, nil, true)
				msg_pi, msg_wait = 1, false
				btn_last = nil                                            -- a new question re-arms the buttons
				say((msg_pages and msg_pages[1]) or t)                    -- page one; the whole line if unsplit
				return                                                    -- one line per frame, message first
			end
			-- LATER PAGES, on the printer's own edge. FUN_0201CD2C's printer parks at a break with state 1
			-- and resume-action 1 (printer+0x00 / +0x04); your A press puts state back to 0. One 1 -> 0
			-- transition is exactly one page. Anything we do not understand (an unreadable printer, a state
			-- above 2) simply stops advancing rather than guessing.
			-- ⛔ LATER PAGES QUEUE, they never interrupt — the standing rule: it is the same screen, so
			-- page two must not cut page one off.
			if msg_pages and #msg_pages > 1 and msg_pi < #msg_pages then
				local pr = u32(sub + 0x64)
				if inram(pr) then
					local pst = u32(pr)
					if pst == 1 and u32(pr + 4) == 1 then
						msg_wait = true
					elseif pst == 0 and msg_wait then
						msg_wait = false
						msg_pi = msg_pi + 1
						local pg = msg_pages[msg_pi]
						if pg then say(pg, false); return end
					end
				end
			end
			-- THE TWO BUTTONS, only while the widget itself says it is taking input.
			local menu = u32(sub + 0x9C)
			if not (inram(menu) and tag_ok(menu, YNTAG)) then btn_last = nil; return end
			if u32(menu + 0x98) ~= 2 then btn_last = nil; return end       -- not accepting input
			local cur = u32(menu + 0xC0)
			if cur > 1 then return end                                     -- transitional: stay silent
			if cur == btn_last then return end
			local lbl = reg.str_text(u32(sub + 0x94 + cur * 4))
			if not lbl then return end                                     -- unreadable label: say nothing
			-- Landing queues behind the question that is still being spoken; moving between the two
			-- interrupts. The same rule the shift prompt, the bag and the party list follow.
			local landing = (btn_last == nil)
			btn_last = cur
			say(lbl .. ", " .. (cur + 1) .. " of 2", not landing)
		end,
	}
end)()

-- 1f) STARTER SELECTION — the ov223 "psel.c" gift-box app (3 Poké Balls) and its private Yes/No.
-- Every live value below belongs to psel itself. The old M+0x24/+0x28 content-sniff was the ExpHeap FREE
-- LIST and is deliberately gone: freed text can never satisfy this module now.
do
	-- ★ THE STARTER APP ITSELF — ov223 "psel.c" (RE'd 2026-07-29, after Ola's dump proved the FIELD
	-- POINTER IS NULL on this screen: gs+0x20 = 0, so NO field reader can ever see this text, which is
	-- why the letter and both prompts went silent when the free-list reader was retired).
	-- It runs on the GameSystem SUB proc manager: gs+0x08 -> +0x08 current proc, vtable 0x021BC8E4
	-- (Black 0x021BC8C4 — its {Init,Main,End} triple byte-matched at a clean -0x20, unique), work =
	-- proc+0x14. psel's own text system, traced in ov223:
	--   work+0x234 message-bank handle — a/0/0/3 FILE 430 (opened by FUN_02045B50(0, 3, 430, heap) at
	--              0x021BAE5C; that factory is the message-archive open, NOT a String create)
	--   work+0x250 live printer   work+0x254 its private task manager   work+0x258 the PRINTED String
	-- The general message fn FUN_021BAFE4(work, msgId) fetches the entry into work+0x258 (@0x021BB028)
	-- and prints it (@0x021BB0AC): **id 0x13 = "Choose a Pokémon."** (call @0x021BBE70) and **id 0x14 =
	-- "Is this the Pokémon you want?"** (call @0x021BC124). Both are live-readable — that is the reader
	-- below. ⛔ The LETTER (id 0x0C) is NOT: FUN_021BB2C4 fetches it into a LOCAL and DIRECT-RENDERS it
	-- (@0x021BB2D2 -> FUN_0201F26C), freeing the String in the same call — exactly why the old debris
	-- reader found it lying in freed memory. It is drawn once from psel's init path (@0x021BBAC6), so we
	-- speak the game's own bank text at that moment, the way the party-list headers already work.
	-- (Bank text verified identical in both ROMs; the other fetches — "Pick this one!" id 0x15 and
	-- YES/NO ids 0x16/0x17 — use LOCAL Strings, so they can never leak into +0x258.)
	local PSEL_VT = 0x021BC8E4 + DELTA
	local PSEL_SPECIES = 0x021BC730 + DELTA   -- Black 0x021BC710, measured in ov223 (same file offset)
	local PSEL_LETTER = "I've brought three Pokémon, one for you and one for each of your friends. "
		.. "Please settle your choices politely. Enjoy your Pokémon! --Professor Juniper"
	local PSEL_OPTION = { "Yes", "No" }      -- a/0/0/3 bank 430 ids 0x16/0x17, in builder order
	local function psel_work()
		local gs = u32(GAMESYS_PTR); if not inram(gs) then return nil end
		local pm = u32(gs + 0x08); if not inram(pm) then return nil end
		local p = u32(pm + 0x08); if not inram(p) then return nil end
		-- GameProc identity, not content: overlay id 223 + exact psel vtable + RUN, with the complete
		-- 0..13 EventState range dispatched by its table. Init writes heap id 0x87 to work+0x00.
		if u32(p + 0x04) ~= 223 or u32(p) ~= PSEL_VT or u32(p + 0x08) ~= 2
			or u32(p + 0x0C) > 0x0D then return nil end
		local w = u32(p + 0x14)
		if not inram(w) or u16(w) ~= 0x87 then return nil end
		return w, p
	end
	-- Outer EventState 9 is the selection state. Its inner state at work+0x0C accepts ball navigation
	-- in states 3..7 and keeps the selected index at work+0x228. The app consumes that same index through
	-- its species table for the rendered description and cry; 0/1/2 map to species 495/498/501.
	local function focused_species(w, p)
		if u32(p + 0x0C) ~= 9 then return nil end
		local st = u32(w + 0x0C); if st < 3 or st > 7 then return nil end
		local c = u32(w + 0x228); if c > 2 then return nil end
		local sp = u16(PSEL_SPECIES + c * 2)
		return (sp >= 1 and sp <= 649) and sp or nil
	end
	-- psel's inner state 10 builds a private app_taskmenu.c object at work+0x264; state 11 polls it.
	-- This is NOT module 1g's BmpMenuList. The library itself reads input only while menu+0x0C == 0,
	-- sets that word to 1 on A/B, and stores the live row in byte +0x00. Requiring all of those facts
	-- suppresses the closing cursor transition and fails closed on any stale or wrong object.
	-- LIVENESS: the exact current ov223 proc is RUNNING in outer state 9, its inner state is precisely
	-- 11 (the only state that polls work+0x264), and the menu's own input state is still zero.
	-- Returns (cursor, rowCount). The COUNT comes from the widget's own u8 +0x24, never from a literal —
	-- the standing rule from the bag menu, where walking a table until it stopped looking valid inflated a
	-- two-row menu to "1 of 4". The `== 2` below stays as a TYPE check on this specific menu (psel builds
	-- exactly YES/NO), so a wrong object still fails closed; the spoken number is the widget's.
	local function yesno_cursor(w, p)
		if u32(p + 0x0C) ~= 9 or u32(w + 0x0C) ~= 0x0B then return nil end
		local m = u32(w + 0x264)
		if not (inram(m) and reg.tag_at(m, "app_taskmenu.c")) then return nil end
		local n = u8(m + 0x24)
		if u16(m + 0x20) ~= u16(w) or n ~= 2 or u32(m + 0x0C) ~= 0 then return nil end
		local c = u8(m)
		if c >= n then return nil end
		return c, n
	end
	local function name_label(sp)
		local names, types, type_names = reg.spname, reg.species_types, reg.type_names
		local ty = types and types[sp]
		if not (names and ty and ty[1] == ty[2] and type_names and type_names[ty[1]]) then return nil end
		local nm = names(sp); if not nm or nm == "" then return nil end
		return nm .. ", the " .. type_names[ty[1]] .. "-type Pokémon"
	end
	local last_species, yn_last, psel_letter, psel_msg
	MODULES[#MODULES + 1] = {
		name = "starter selection",
		-- Exact current-proc identity makes the old battle/party/shop stand-downs redundant: none of those
		-- contexts can simultaneously be the RUNNING overlay-223 CurrentProc on this manager.
		detect = function() return psel_work() ~= nil end,
		on_enter = function() last_species, yn_last, psel_letter, psel_msg = nil, nil, false, nil end,
		update = function()
			-- The app's own text, first: the baked letter once per visit (it is drawn and thrown away, so
			-- there is nothing to read), then whatever psel is currently printing — "Choose a Pokémon."
			-- when no ball is picked, "Is this the Pokémon you want?" when you press A. Both queue, so the
			-- Pokémon line and the Yes/No below follow in the order they appear on screen.
			local w, p = psel_work(); if not w then return end
			if not psel_letter then psel_letter = true; say(PSEL_LETTER) end
			local t = reg.str_text(u32(w + 0x258))
			if t and t ~= psel_msg then psel_msg = t; say(t, false) end
			-- Yes/No takes priority once it's up (you confirm the pick through it).
			-- ⚠ SPOKEN AS "<option>, X of Y" — Ola, 2026-08-31, testing this screen: "in the starter yes no,
			-- ad index, one of 2, and stuff, make it properly there". Every menu in this project announces
			-- in that one form, and this one had been the odd one out since it was written.
			local c, n = yesno_cursor(w, p)
			if c ~= nil then
				local line = PSEL_OPTION[c + 1] .. ", " .. (c + 1) .. " of " .. n
				if yn_last == nil then yn_last = c; say(line, false)          -- queue after the question
				elseif c ~= yn_last then yn_last = c; say(line, true) end     -- navigation: interrupt
				-- ⚠ RE-ARM THE BALL LINE HERE, and ONLY here (Claude cross-review 2026-08-31). The rewrite
				-- dropped the old reader's `else last_name = nil`, so backing out of the confirm returned you
				-- to the ball you were already on and said nothing — and Ola's rule is that arriving at a
				-- screen speaks. Re-arming on any nil read instead would be wrong: focused_species is also
				-- nil on inner states outside 3..7, so a transient during navigation would repeat the ball
				-- you never left. The confirm being UP is the real "you left the ball screen" event.
				last_species = nil
				return
			end
			yn_last = nil
			-- otherwise announce the focused Pokémon (with its type) as you move between balls.
			local sp = focused_species(w, p)
			if sp ~= nil and sp ~= last_species then
				local line = name_label(sp)
				if line then
					say(line, last_species ~= nil)   -- first landing queues; moving balls interrupts
					last_species = sp
				end
			end
		end,
	}
end

-- Set by the PARTY SCREENS section below: true while a party-family PROC (party list / summary) is the
-- CurrentProc. The field script-menu reader must stand down there — its chain reads the FIELD's active-menu
-- global, which can hold a stale (freed but intact) BmpMenu from an earlier prompt while a party app
-- runs; claiming the context on that stale object silences every party reader below it in the list.

-- 1f2) POKÉ MART — the BUY screen: the item list (name + price + description), the quantity select, and
-- the final Yes/No confirm. RE 2026-08-08 (Ghidra, ov021 @ 0x02187F20; every offset below read from the
-- instruction that USES it, not from a store). Banked: white.lua "POKÉ MART (SHOP)" + accessibility-docs/20.
--
-- ⛔ THE ANCHOR WAS ALREADY HERE AND IT WAS OFF BY 8 — which is exactly why shop messages were silent.
-- `Shop_Start` (FUN_021b2ff8) allocates 0x214 bytes tagged "scrcmd_shop.c" and starts the outer field task
-- FUN_021b3178. That outer task's case 4 is, in raw thumb at 0x021b31fc:
--     ldrb r2,[r4,#2] ; adds r1,r4,#0 ; ldrb r3,[r4,#3] ; adds r0,r7,#0 ; adds r1,#8 ; bl 0x21b35c4
-- so the shop UI's own work struct starts at **shop+8**, and every offset the UI code uses is relative to
-- THAT, not to the tagged allocation. The 2026-07-28 registry note recorded the manager as "shop +0x1B4"
-- when 0x1B4 is the WORK-relative offset — u32(shop+0x1B4) reads work+0x1AC, a byte flag, so
-- printer_in_manager() rejected it every time and the mart's own dialogue never spoke. Fixed in
-- reg.printer() above (shop + WORK + 0x1B4). Same correction applies to the String at work+0x198 and the
-- printer at work+0x1B8 recorded in white.lua.
--
-- OUTER task states (u8 at shop+0): 0/1 field fade, 2 init camera, 3 wait camera, **4 = the shop UI owns
-- the screen**, 5/6 restore, 7 end. So `u8(shop)==4` is the game's own "the mart screen is up" predicate.
-- INNER UI states (u8 at work+0), from the jump table at 0x021b35de:
--   1  = BUY LIST browsing   (FUN_021b3490)          <- we speak the highlighted row
--   2  = quantity screen setup (one frame) -> 3
--   3  = QUANTITY select     (FUN_021b4ac4: Up +1, Down -1, Right +10, Left -10)  <- we speak qty + total
--   4  = back to the list    5/6 = build the Yes/No -> 7
--   7  = the final YES/NO    (FUN_0201fed8 on work+0x184; YES returns 0, NO returns -2)  <- we speak it
--   8/9 = purchase finish (9 = the free Premier Ball when you buy 10+ Poké Balls)
--   10 = message wait   11 = teardown
-- FIELDS (work-relative, each proven at its use):
--   +0x20 + i*8 : u16 item id, and +4 = u32 price. Built by FUN_021b3900, which also writes the goods
--                 count to +0x160 and adds a final CANCEL row carrying value -2.
--   +0x160 s16  : number of goods rows (excludes Cancel).
--   +0x184      : the Yes/No widget (a 0x38-byte GRID BmpMenu from FUN_0201f958 — **NOT** the 0x50-byte
--                 bmp_menulist the rest of the game uses, so its cursor is NOT at +0x40/+0x42). Its input
--                 reader FUN_0201fa20 does, on A: `ldr r1,[r5] ; ldrb r0,[r5+0x2d] ; lsls r0,#3 ;
--                 ldr r0,[r1+r0+4]` — so **+0x00 = the entry array (stride 8: String*, value)** and
--                 **+0x2D = the live cursor index**; +0x09 = columns, +0x0A = rows (FUN_0201fb4c).
--   +0x1A4      : the item ListMenu (the ordinary bmp_menulist — same layout module 1g reads).
--   +0x1FC u16  : chosen item id   +0x200 u32 : unit price   +0x204 : max quantity   +0x208 s16 : quantity.
-- ITEM NAMES come from the rows' OWN Strings, so the game supplies every word: FUN_021b3900 builds the
-- StringList at work+0x180 with StringList_AddFromMessageBank(bank 0x36 = item names) and frees only the
-- MessageLoader afterwards (0x021b39c8), never the Strings — the safe direction of the one-way-facts rule.
-- The DESCRIPTION is the opposite case and must NOT be read live: FUN_021b4284 fetches it fresh on every
-- cursor move (`ldr r0,[r5+0x18c] ; blx 0x2045ed8`), draws it, and FREES it four instructions later at
-- 0x021b42ca. So we use the offline bake (ITEM_DESC), which is the same ROM text the window shows.
do
	local SH_TAG, SH_WORK = "scrcmd_shop.c", 8
	local CANCEL_VAL = 0xFFFFFFFE                      -- the Cancel row's value (-2 as unsigned)
	-- The live shop UI work area, or nil. Fails closed at every hop; the allocator tag re-proves identity
	-- and `u8(shop)==4` is the game's own gate for "the mart screen, not the camera pan or the greeting".
	local function shop_work()
		local env = reg.gs_task(reg.SHOP_CB); if not env then return nil end
		local sw = u32(env); if not inram(sw) then return nil end
		local shop = u32(sw + 0x3C); if not inram(shop) then return nil end
		-- LIVENESS: the tag proves WHAT this object is; what proves it is still ALIVE is the route we took
		-- to it — reg.gs_task(SHOP_CB) only returns a task that is ON the GameSystem task chain this frame,
		-- and scriptWork+0x3C is re-read from that task every time. When the mart ends, the task leaves the
		-- chain and this returns nil at the first hop; the pointer is never cached across frames.
		if not reg.tag_at(shop, SH_TAG) then return nil end
		if u8(shop) ~= 4 then return nil end
		return shop + SH_WORK
	end
	reg.shop_active = shop_work   -- registry: module 1f (starter selection) stands down on this, above
	-- The highlighted list row: its own text, its value, and where it sits. Any unreadable row yields nil
	-- and we stay silent — never a guessed word (the standing rule; module 1g learned it the hard way).
	local function list_row(w)
		local m = u32(w + 0x1A4); if not inram(m) then return nil end
		local arr, n = u32(m + 0x00), u16(m + 0x10)
		if not inram(arr) or n == 0 or n > 64 then return nil end
		local raw = u16(m + 0x40) + u16(m + 0x42)
		if raw >= n then return nil end
		local txt = reg.str_text(u32(arr + raw * 8)); if not txt then return nil end
		return txt, u32(arr + raw * 8 + 4), raw, n
	end
	local function list_line(w)
		local txt, val, raw, n = list_row(w); if not txt then return nil end
		local out = { txt }
		if val ~= CANCEL_VAL and val < u16(w + 0x160) then      -- a real item, not the Cancel row
			out[#out + 1] = tostring(u32(w + 0x24 + val * 8))   -- the price the row itself shows
			local d = reg.item_desc[u16(w + 0x20 + val * 8)]
			if d and d ~= "" then out[#out + 1] = d end
		end
		out[#out + 1] = (raw + 1) .. " of " .. n
		return table.concat(out, ", "), raw
	end
	-- "5, 1250" — QUANTITY then TOTAL, and nothing else (Ola, in-game 2026-08-08: "on this screen I only
	-- need quantity and price not name"). It is exactly what the box shows ("x 5" and "₽ 1250"); the item
	-- was named by the message right above it, and repeating it on every press of up/down pushed the one
	-- number you are actually changing to the end of the line.
	-- The total is the game's own arithmetic, verified at its use: FUN_021b42f0 does `muls r2, r7, r2`
	-- at 0x021b4392 (quantity x unit price) before formatting it into the currency template.
	-- ⛔ BOUND IT BY THE GAME'S OWN MAXIMUM, not by a round number (codex-review 2026-08-08). The first
	-- version accepted anything up to 999 while its own comment said the range was 1..99, and ignored
	-- work+0x204 — the maximum the game itself computed for THIS purchase (money/price, capped at 99, then
	-- clamped again by how many more of the item your bag can hold). FUN_021b4ac4 clamps the quantity
	-- against exactly that field (`*(uint *)(work+0x204) & 0xffff`), so anything outside it means we are
	-- not looking at what we think we are — and on a screen about spending money, a plausible-but-false
	-- number is the worst possible output. Validate the maximum itself first, then the quantity against it.
	local function qty_line(w)
		local q, unit, hi = u16(w + 0x208), u32(w + 0x200), u16(w + 0x204)
		if hi < 1 or hi > 99 then return nil end
		if q < 1 or q > hi then return nil end
		return q .. ", " .. (q * unit), q
	end
	-- The widget itself is the engine's grid BmpMenu, shared with the title screen's C-Gear prompts —
	-- the layout and its evidence live once, in reg.grid_yesno.
	local function yn_line(w)
		return reg.grid_yesno(u32(w + 0x184))
	end
	-- SCREENS, not states: the UI has more states than screens, and state 2 (quantity setup) falls through
	-- to state 3 in the same frame. Keying the "have I said this" memory on the raw state would announce the
	-- quantity line twice — once for 2, once for 3 — depending on which side of the game's own task our
	-- frame lands. Collapse them here, once, so the rest of the module cannot get it wrong.
	local function screen_of(st)
		if st == 1 then return 1 end                  -- the buy list
		if st == 2 or st == 3 then return 2 end       -- the quantity selector
		if st == 7 then return 3 end                  -- the final Yes/No
		return nil                                    -- init / messages / paying / teardown: we say nothing
	end
	-- MONEY (Ola's request 2026-08-08: a key that tells you your money, on the shop screens only).
	-- Taken from the game's own getter rather than a guessed profile field. The shop's affordability check
	-- FUN_021b3370 reads u32(work+0x0C) through FUN_0200C274, and FUN_0200C274 is literally
	-- `return *(u32*)obj`. That object is a SAVE BLOCK: FUN_02012f08 is `r0 = u32(gs+0) ; b FUN_0200C0F0`
	-- and FUN_0200C0F0 is `SaveControl_GetBlock(save, 0x34)` (`movs r1,#0x34 ; bx`).
	-- The block getter FUN_020319bc = `u32(desc+0x34) + FUN_02033b80(u32(desc+0x2c), id)`, and
	-- FUN_02033b80 = `u32( u32(tbl+0x14) + id*0xC + 8 )`, bounds-checked against u32(tbl+4).
	-- ⭐ This is the SAME descriptor manager player_name() already walks — which is why its live block is
	-- u32(mgr+0x34) — so we can now resolve ANY save block by id instead of hardcoding one offset. Money
	-- is block 0x34. Reached from the fixed GameData chain, so it works on every screen, not just the shop.
	-- Generalised 2026-09-03 for the TRAINER CARD, which needs block 0x21 (the card's own extras:
	-- the signature bitmap, the badge dates, and the flag that decides whether the trainer-class title
	-- is the player's real class or the game's default one). Same walk, id as a parameter.
	local function save_block(id)
		local gd = find_gd(); if not gd then return nil end
		local sc = u32(gd); if not inram(sc) then return nil end
		local mgr = u32(sc + 0x10); if not inram(mgr) then return nil end
		local tbl = u32(mgr + 0x2C); if not inram(tbl) then return nil end
		if u32(tbl + 4) <= id then return nil end            -- the game asserts on this; we just fail closed
		local recs = u32(tbl + 0x14); if not inram(recs) then return nil end
		local blk = u32(mgr + 0x34); if not inram(blk) then return nil end
		local a = blk + u32(recs + id * 0xC + 8)
		return inram(a) and a or nil
	end
	reg.save_block = save_block
	local function money()
		local a = save_block(0x34)                           -- money is the block's first word
		return a and u32(a) or nil
	end
	reg.money = money
	local last_scr, last_key, last_msg, after_msg
	MODULES[#MODULES + 1] = {
		-- Registered BEFORE module 1g on purpose: the mart is opened by a field SCRIPT, so 1g's chain
		-- (scriptEnv+0x148 -> menuWork+0x50) can still hand back the closed BUY/SELL/QUIT menu — intact
		-- and tag-valid — for as long as the shop runs. It would not speak (it keys on the menu instance),
		-- but it WOULD claim the context and starve this reader, which is the exact failure mode the party
		-- screens hit in August. First match wins, so order is the fix.
		name = "poke mart",
		detect = function() return shop_work() ~= nil end,
		on_enter = function() last_scr, last_key, last_msg, after_msg = nil, nil, nil, false end,
		update = function()
			local w = shop_work(); if not w then return end
			local st = u8(w)
			-- ── THE SHOP'S OWN MESSAGES (fixed 2026-08-08 after Ola tested) ─────────────────────────────
			-- "Ice Heal? Certainly. How many would you like?" was not spoken at all, and a fragment ("Ice")
			-- arrived just before the quantity. Both are one cause. The shop prints through an ordinary
			-- RenderText printer (FUN_021b4734 -> FUN_0201CD2C at 0x021b47f2, manager work+0x1B4), but the
			-- messages that AUTO-ADVANCE are torn down the moment they finish drawing, so the global
			-- progressive reader — which speaks what has been drawn SO FAR — caught three glyphs and then
			-- the printer was gone. The messages that WAIT for A live for many frames, which is exactly why
			-- some of them read perfectly and this one did not.
			-- So the shop now owns its text: read the String the game itself just formatted. State 10 is the
			-- game's OWN "a message is up" state, and gating on it is what makes this safe — work+0x198 is a
			-- SHARED SCRATCH String (the per-row price is formatted into that very same String while the
			-- LIST draws, FUN_021b4530), so this is a state-gated read, not the content-watch that burned us
			-- on the bag's work+0x528. reg.printer() skips the shop branch while this module is live, so the
			-- two readers can never both speak. ALWAYS QUEUES: a message must never cut the game off.
			-- ⛔ INTERRUPT/QUEUE (Ola's standing rule, spelled out 2026-08-08 — see CLAUDE.md "SPEECH FLOW"):
			-- the FIRST thing said on a NEW SCREEN interrupts; everything else on that same screen queues
			-- behind it; moving the cursor always interrupts. A message is the first thing on the screen it
			-- introduces, so it interrupts — and the quantity that follows queues, because it is the same
			-- screen. A SECOND page of the same message queues rather than cutting the first (last_msg is
			-- nil only on the frame we arrive in state 10, which is what distinguishes the two).
			if st == 10 then
				local t = reg.str_text(u32(w + 0x198))
				if t and t ~= last_msg then
					local arriving = (last_msg == nil)
					last_msg = t
					say(t, arriving)
					after_msg = true          -- whatever this screen shows next queues behind it
				end
			else
				last_msg = nil          -- cleared on leaving, so the same message shown twice speaks twice
			end
			local scr = screen_of(st)
			if scr ~= last_scr then last_scr, last_key = scr, nil end   -- a new screen always re-announces
			if not scr then return end
			local line, key
			if scr == 1 then line, key = list_line(w)
			elseif scr == 2 then line, key = qty_line(w)
			else line, key = yn_line(w) end
			if not line or key == nil then return end
			key = scr .. ":" .. key
			if key == last_key then return end
			local first = (last_key == nil)
			last_key = key
			if first then
				-- Landing on a new screen. It INTERRUPTS whatever was still being said for the screen you
				-- just left — unless this screen's own message has just spoken, in which case we queue
				-- behind it so the two arrive in the order they appear ("...how many would you like?" then
				-- "5, 1250"). That is the whole rule in one line.
				say(line, not after_msg)
				after_msg = false
			else
				say(line, true)   -- the number / cursor moved: interrupt, so fast changes collapse to the latest
			end
		end,
	}
end

-- 1g) FIELD SCRIPT MENUS — every choice list a field script puts up: the PC list in a Pokémon Center
-- ("Someone's PC / <name>'s PC / Professor's PC / Help / Switch off"), Nurse Joy's "heal your Pokémon?",
-- shop and NPC prompts. All of them are ONE widget, the Gen V BmpMenuList.
-- ⛔ THERE ARE **TWO** BUILDERS, AND THE PC USES THE ONE WE HAD NEVER TRACED (Ola, 2026-08-05: after the
-- row-count fix the probe still said "no menu found", and he was right that the answer was to go read what
-- the PC actually does rather than keep adjusting the old chain). Both end in the same BmpMenuList widget,
-- but they are reached completely differently — traced through ov021 (Ghidra):
--   FUN_02190880 is the shared builder; it allocates a 0x14-byte WRAPPER and puts the widget at wrapper+0x10.
--   (a) SCRIPT MULTI-CHOICE (the PC list, and every scripted choice prompt) — builder FUN_021909A8, called
--       by the script command handler **FUN_0215A884**, whose last act is `*(menuWork + 0x50) = wrapper`.
--       The handler reads the menu work as `u32(scriptCtx + 0x20)`, and the context ctor FUN_0215A57C fills
--       that field from `FUN_02158F8C(X)` = `return *(X + 0x148)`.
--       ⛔ X IS **NOT** THE FIELD — that assumption was my second wrong answer here (2026-08-05) and it is
--       why the reader stayed silent after the first fix: u32(Field+0x148) is an unrelated field of a much
--       bigger struct, so it read garbage and failed closed. X is the **0x14C-byte SCRIPT ENVIRONMENT**
--       allocated by FUN_02158E9C, which sets its own `puVar1[0x52]` (= byte 0x148) from FUN_0215A534.
--       The size is the tell: a 0x14C-byte object has a +0x148; the 0x24-byte script CONTEXT does not, and
--       the Field's +0x148 means something else entirely.
--       WHERE THE ENV LIVES — through the script system, as it should be. FUN_02158940 builds the VM as a
--       **GS TASK**: `task = FUN_020122C0(...)`, `taskEnv = FUN_020124E8(task)` (= u32(task+0x0C)), then
--       `taskEnv[0] = FUN_02158E9C(...)`. So:
--       ⇒ task = u32(0x0224F784 + DELTA) [= gs+0x18, the task-stack head we already read]
--         scriptEnv = u32( u32(task + 0x0C) ) ; menuWork = u32(scriptEnv + 0x148)
--         **menu = u32( u32(menuWork + 0x50) + 0x10 )**
--       We WALK the task chain by task+0x00 (the parent link the runner itself follows) because a message
--       task can sit above the script task. Bounded list walk, never a RAM scan.
--   (b) YES/NO (Nurse Joy and friends) — builder FUN_02190C04, which hardcodes a row count of 2 and is
--       called from a different subsystem (FUN_021B00A4). That one is the old, already-working path:
--       menu = u32( u32( u32(0x0224F784 + DELTA) + 0x48 ) + 0x10 ).
-- We try (a) then (b). Keeping both is safe rather than sloppy: each is independently proven by the
-- "bmp_menulist.c" allocator tag at obj-0x18, so a wrong guess yields nil, never a wrong word.
-- The question text is read by the always-on dialogue reader; this adds the options.
-- (Distinct from the STARTER Yes/No — module 1f, checked first, held-object path.)
--
-- ⛔ THIS USED TO BE A YES/NO-ONLY READER AND THAT IS WHY THE PC WAS SILENT (Ola, 2026-08-05, screenshot:
-- the question spoke, the five PC options did not). It ended with `return (v <= 1) and v or nil` — a
-- hard-wired two-row assumption — and its labels were the literal strings {"Yes","No"}. Any menu with more
-- than two rows failed the guard, so the module never claimed the context and nothing below it spoke either.
-- Fixed by reading the widget instead of assuming it, which is the standing rule (CLAUDE.md: take the row
-- COUNT from the widget, and read the ROW'S OWN String rather than mapping ids to hardcoded English).
-- STRUCT, from the ctor FUN_0201FF4C (Ghidra; it is the only xref to the tag string at 0x020A73B0):
--   the object is 0x50 bytes; the first 0x34 are copied verbatim from the caller's parameter block.
--   u32(m + 0x00) = ENTRY ARRAY, stride 8 = { u32 text*, s32 value } (the Gen IV/V ListMenuItem).
--   u16(m + 0x10) = TOTAL entries. Proven by the ctor clamping the window height at +0x12 against it
--                   (`if u16(+0x10) < u16(+0x12) then u16(+0x12) = u16(+0x10)`), so +0x10 is the real count
--                   and +0x12 is only how many rows are visible at once.
--   u16(m + 0x40) + u16(m + 0x42) = the live cursor (scroll base + offset in the window) — unchanged.
--   value == -3 marks an UNSELECTABLE row: the ctor itself walks the cursor forward while it lands on one
--   (`while *(entries + idx*8 + 4) == -3 do idx++ end`), so we drop those rows and index within what is left.
-- Row text is decoded StrBuf-first (self-identifying by magic, so a hit is certain) then raw charcodes with
-- a printable-ratio floor; an unreadable row goes SILENT rather than guessing. This also means menus we have
-- never opened read correctly, because the game supplies every word.
do
	local MTAG = { 0x62,0x6D,0x70,0x5F,0x6D,0x65,0x6E,0x75,0x6C,0x69,0x73,0x74,0x2E,0x63 }   -- "bmp_menulist.c"
	local function menu_tagged(o)
		if not inram(o - 0x18) then return false end
		for i = 0, #MTAG - 1 do if u8(o - 0x18 + i) ~= MTAG[i + 1] then return false end end
		return true
	end
	-- TWO SOURCES, because there are genuinely TWO builders (see the header above): the SCRIPT multi-choice
	-- menu (the PC list) hangs off the Field, and the Yes/No prompt is built by a different subsystem and
	-- hangs off the GS task. Both end in the SAME widget and both are proven by the same allocator tag, so
	-- neither can hand us the wrong object — a miss just yields nil. This is not an id-table fallback; each
	-- source is independently self-validating.
	local LIST_MENU_CB = 0x021B017D + DELTA   -- FUN_021B017C|1, the script list-menu task callback
	local YESNO_CB     = 0x021B00A5 + DELTA   -- FUN_021B00A4|1, the Yes/No task callback
	local function via_wrapper(w)
		if not inram(w) then return nil end
		local m = u32(w + 0x10)                     -- builder FUN_02190880: wrapper+0x10 = the BmpMenuList
		if not (inram(m) and menu_tagged(m)) then return nil end
		-- LIVENESS: proved by the CALLER — every menu here comes from a GS task that is on the chain now and
		-- reads state 2, the state in which its callback is actively polling it (list menu FUN_021B017C, or
		-- Yes/No FUN_021B00A4). The pair check below is only a cheap consistency test, NOT a liveness proof:
		-- both the tag and this duplicated pointer survive teardown, which is why it was never enough.
		-- ⛔ CROSS-CHECK THE PAIR. A tag proves WHAT an object is, never that it is still LIVE — freed memory
		-- keeps its tag until something else claims it, and Ola kept hearing his own name read as a one-row
		-- menu from exactly such a corpse. The builder writes the entry array to BOTH objects
		-- (`puVar3[3] = param_3` = wrapper+0x0C, and params[0] -> menu+0x00), so while they are the live pair
		-- those two words are equal. Once either is freed and reused they diverge. Cheap, and derived from
		-- the builder rather than invented.
		if u32(w + 0x0C) ~= u32(m + 0x00) then return nil end
		return m
	end
	local function menu_obj()
		-- ⛔⛔ BOTH MENU KINDS ARE NOW GATED ON THEIR OWN LIVE TASK (Codex trace + verified here, 2026-08-06).
		-- Neither the allocator tag nor any field of the objects proves they are alive: choosing an entry FREES
		-- the rows, the widget and the wrapper (FUN_0215A974 -> FUN_0215A940) WITHOUT clearing the pointer that
		-- addresses them, and both the tag and the duplicated entry-array word survive that. Reading the corpse
		-- is what announced Ola's trainer name as a one-row menu for four rounds.
		-- Each menu instead lives inside a GS task, and the TASK is the proof. Both run the same shape and,
		-- pleasingly, both are live in **state 2**:
		--   SCRIPT LIST MENU — callback FUN_021B017C: st0 set up, st1 build (calls the menu command handler
		--     FUN_0215A884), **st2 poll the live menu** (and free it there on selection).
		--     menu = env[0] -> scriptCtx, +0x20 menuWork, +0x50 wrapper, +0x10 widget.
		--   YES/NO — callback FUN_021B00A4: st0/1 build (FUN_02190C04, the builder that hardcodes 2 rows) and
		--     store the wrapper at **env[2]**, **st2 poll** (func_0x02190C98 returns 2 while still waiting),
		--     st3 destroy. So the wrapper is env+0x08 — NOT the task+0x48 the old code guessed at, which had no
		--     liveness proof at all and was the last ungated read in this module.
		-- (GS task struct, banked: +0x00 next, +0x04 callback, +0x08 state, +0x0C env.)
		local t, guard = u32(A.active_menu_ptr), 0
		while inram(t) and guard < 16 do
			if u32(t + 0x08) == 2 then                       -- the live state for BOTH kinds
				local cb, env = u32(t + 0x04), u32(t + 0x0C)
				if inram(env) then
					if cb == LIST_MENU_CB then
						local ctx = u32(env)
						local mw = inram(ctx) and u32(ctx + 0x20) or 0
						if inram(mw) then
							local m = via_wrapper(u32(mw + 0x50))
							-- Hand back the menu WORK too: its +0x54 array holds this menu's per-row
							-- descriptions. Only for THIS task; the Yes/No sibling has no such array.
							-- u32(menu+0x1C) is the menu's own back-pointer to the script context, which
							-- the cursor callback checks before it will read anything (FUN_0215A9E0).
							if m and u32(m + 0x1C) == ctx then return m, mw end
						end
					elseif cb == YESNO_CB then
						local m = via_wrapper(u32(env + 0x08))
						if m then return m end
					end
				end
			end
			t = u32(t)
			guard = guard + 1
		end
		return nil
	end
	-- One row's own words. StrBuf first (self-identifying: magic + len<=cap + terminator, so a hit is
	-- certain), then a raw charcode buffer with a printable-ratio floor. Both FAIL CLOSED — an unreadable
	-- row yields nil and we stay silent for it rather than inventing a word.
	local function row_text(p)
		if not inram(p) then return nil end
		local t = reg.str_text(p)
		if t then return t end
		local s, ratio = im_decode(p)
		if s and #s > 0 and #s <= 60 and ratio and ratio >= 0.9 then return s end
		return nil
	end
	-- The selectable rows, in screen order, plus where the cursor is among them.
	local function menu_rows(m)
		local n = u16(m + 0x10)                              -- TOTAL entries (ctor clamps +0x12 against it)
		if n == 0 or n > 24 then return nil end
		local arr = u32(m + 0x00); if not inram(arr) then return nil end
		local cur = u16(m + 0x40) + u16(m + 0x42)            -- scroll base + offset within the window
		local list, at = {}, nil
		for i = 0, n - 1 do
			if u32(arr + i * 8 + 4) ~= 0xFFFFFFFD then       -- value -3 = separator; the ctor skips these too
				local txt = row_text(u32(arr + i * 8))
				-- ⛔ FAIL CLOSED ON ANY UNREADABLE ROW. `list[#list+1] = nil` does not grow the table, so a
				-- row that failed to decode used to shift every later row up one — and the cursor could then
				-- be announced with a DIFFERENT row's words. Speaking the wrong option is far worse than
				-- silence, and it was live in the code until Codex's review caught it (2026-08-06).
				if not txt then return nil end
				list[#list + 1] = txt
				if i == cur then at = #list end
			end
		end
		if not at or not list[at] then return nil end
		return list, at, cur   -- cur = the RAW row; the description array is indexed by it
	end
	-- ⛔ KEYED TO THE MENU INSTANCE, NOT TO MODULE ENTRY (Ola 2026-08-06: choosing "Move Pokemon" spoke the
	-- EARLIER PC-selection menu back at him, "<name>'s PC"). When a menu closes, menuWork+0x50 still exposes
	-- a menu object, so this module briefly reactivates; resetting `last` in on_enter made it re-announce the
	-- very row he had just chosen. Now the "have I said this" memory is keyed to the object AND its shape, so
	-- a menu that reappears unchanged stays silent, and only a genuinely different one speaks. This can never
	-- produce a WRONG word — the worst case is silence until the cursor moves.
	-- ⛔ THE PER-ROW DESCRIPTION ("Pokemon in your party may be stored in the storage system's Boxes.").
	-- Ola had never heard these and assumed they did not exist. Our always-on dialogue reader could NEVER
	-- have found them, which is why my earlier guess that it was reading them and being cut off was wrong:
	-- the cursor callback renders them via FUN_021911A4 -> FUN_021905B0 -> FUN_0201C718 -> FUN_0201C774,
	-- straight into the grey window, and never calls FUN_0201CD2C — the function that creates the ordinary
	-- RenderText printer task our reader walks. Same window on screen, different route entirely.
	-- The text is a live StrBuf per row in a parallel array: **u32(menuWork + 0x54 + rawRow*4)**, expanded
	-- and duplicated at build time (FUN_0215A810) and read back by the cursor callback FUN_0215A9E0 at
	-- 0x0215A9EA..0x0215AA02. Origin: script opcode 0x00AF ListMenuAdd, operands {row text id, DESCRIPTION
	-- id, result} — no static table, the ids sit inline in the script. For the PC they resolve in a/0/0/3
	-- bank 314, and I checked [20] is verbatim the sentence off Ola's screen. (Codex trace 2026-08-06.)
	local DESC_DRAWN = 0x02172BC0 + DELTA   -- bit 1 set = the description window is actually being drawn
	local function row_desc(mw, raw)
		if not (mw and inram(mw)) then return nil end
		if (u32(DESC_DRAWN) & 0x02) == 0 then return nil end   -- the callback's own gate, transcribed whole
		return reg.str_text(u32(mw + 0x54 + raw * 4))
	end
	local last, last_key, app_seen, said = nil, nil, nil, {}
	local function menu_key(m, list)
		return string.format("%08X/%d/%s", m, #list, tostring(list[1]))
	end
	MODULES[#MODULES + 1] = {
		-- NOT "field menu" — that name belongs to the overworld X/Start menu (field_menu.c) further down.
		-- context_of() logs the active module's name, and after 2026-08-04 an ambiguous speaker label is
		-- exactly the thing we do not ship.
		name = "field script menu",
		detect = function()
			-- Remember that a field app owned the screen, so on_enter can tell "the menu never closed" from
			-- "you came back out of the PC". Without this, backing out of Deposit onto the SAME row of the
			-- PC's own menu was suppressed as a duplicate and said nothing (Ola 2026-08-06) — while backing
			-- out of Withdraw did speak, only because the cursor happened to land on a different row.
			if pc_box_closed then app_seen = true end
			-- ⛔ STAND DOWN INSIDE A FIELD APP (Ola 2026-08-05: opening the PC spoke "<player name>, 1 of 1"
			-- during a transition). The PC selection list is torn down when you choose an entry, but the
			-- object stays readable for a while, so this reader re-announced a DEAD menu whose first row was
			-- "<name>'s PC". While a field app (ov170 and friends) owns the screen, a field script menu is
			-- not what you are looking at. Same stand-down the party screens already get.
			if pc_box_active and pc_box_active() then return false end
			if battle_active() or (party_proc_active and party_proc_active()) then return false end
			local m = menu_obj()
			return m ~= nil and (menu_rows(m)) ~= nil
		end,
		on_enter = function()
			-- Only forget what we last said if a field APP has been up since. A menu that merely flickered
			-- (the torn-down PC list) must still be suppressed; a menu you have genuinely returned to must not.
			-- ⛔ CLEAR EVERY TIME. `said` exists to stop ONE menu re-announcing the row it is already sitting
			-- on; it must NOT survive the menu closing. It used to, so stepping out of the PC's second menu
			-- back to the first (and back in again) announced nothing — both were sitting on the row they
			-- were left on (Ola 2026-08-06). Keeping it across visits was only ever a workaround for the
			-- freed-menu ghost, and that is now gated properly on the live task, so the workaround can go.
			last, last_key, app_seen, pc_box_closed, said = nil, nil, false, false, {}
		end,
		update = function()
			local m, mw = menu_obj(); if not m then return end
			local list, at, raw = menu_rows(m); if not list then return end
			local key = menu_key(m, list)
			-- ⛔ REMEMBER THE ROW PER MENU, not just for the current one. Choosing an entry pops that menu and
			-- re-exposes the one BENEATH it, sitting on the row you picked there earlier — which is how
			-- "<name>'s PC" kept coming back while the PC opened. A frame-count guard did not help, because on
			-- the Move path that menu lingers for far longer than a flicker. Keyed like this it is exact:
			-- returning to a menu on the very row we already announced for it is silent, any other row speaks,
			-- and the whole memory is wiped when you come back out of the PC (pc_box_closed) so a genuine
			-- return always reads.
			local prev = said[key]
			if prev == at then last_key = key; return end
			-- ⛔ "FIRST" MEANS FIRST FOR *THIS* MENU, not first since the script loaded. It used to be
			-- `last_key == nil`, i.e. true only once ever — so every later prompt INTERRUPTED, and Nurse
			-- Joy's "Would you like me to heal your Pokemon?" was cut off by its own Yes (Ola 2026-08-06).
			-- Landing on a menu queues so it follows the question; moving the cursor inside it interrupts.
			local first = (prev == nil)
			said[key] = at
			last, last_key = at, key
			-- ORDER: name, then the description, then the index (Ola, 2026-08-06 — for THIS menu; the box
			-- grid keeps name-then-index-then-details, which is what he asked for there). ONE call, so
			-- nothing can interrupt anything else. First landing QUEUES so it follows any question already
			-- being spoken; moving the cursor INTERRUPTS.
			local line = list[at]
			local d = row_desc(mw, raw)
			if d then line = line .. ", " .. d end
			line = line .. ", " .. at .. " of " .. #list
			say(line, not first)
		end,
	}
end

-- 3b0) PARTY SCREENS — the Pokémon party list (field), the summary screen, and the in-battle party list.
-- Full RE 2026-07-23 (Ghidra; accessibility-docs/19-party-screens.md; anchors banked in white.lua):
--   FIELD party list = ov091 "pokelist.c", a GameProc: vtable 0x021BED20 {Init 0x021B6260, Main 0x021B65D8,
--     End 0x021B6554}, subsystem 0x284 bytes on its own heap 0x17 (u16 heap id at sub+0). sub+0x280 -> the
--     0x98-byte launch args ("PartyMenu": +0x00 Party*, +0x34 MODE, +0x3C result slot, +0x40 exit code,
--     +0x44 item id, +0x46 move id). sub: +0xC state (2/3/4 = browse states, 5 = swap anim [silent],
--     6 = A-menu, 7/9 = message [printer reader speaks those], 0xC = multi-confirm, 0x13.. = exit),
--     +0x2C cursor (0-5 mons, 6 = Confirm, 7 = Cancel), +0x30 switch-mark, +0x38 selected mon*,
--     +0x160+i*4 plate objs (+0x00 mon*, +0x1C entry order 0-5 / 6 = none), +0x154 A-menu obj
--     (+0x00 count, +0x02 u16 action ids, +0x74 -> widget, cursor = u8 widget+0). Action ids: 0 Summary,
--     3 Switch, 4 Item, 5 Mail, 6 Quit, 7/0xB Enter, 9 Give, 0xA/0xD Take, 0xC Read, 0xE Store,
--     0x10+slot = the mon's field move in that move slot, 0x14 Enter / 0x15 No entry (multi).
--     Text = a/0/0/2 bank 157 (prompts + button labels; messages spoken by the always-on printer reader).
--   SUMMARY = ov131 "p_status.c", GameProc vtable 0x021DC820 {0x021D6344,0x021D65DC,0x021D659C}, heap 0x42,
--     sub 0x264 bytes: +0x08 args {+0x00 Party*, +0x0C src type (1 party/2 box), +0x0D mode (2 = pick a
--     move to forget), +0x0E count, +0x0F index, +0x10 start page}, +0x18 mon index (u16), +0x5C page
--     (0 info [static] / 1 moves / 2 third page / 3 moves-locked), +0x90 moves-page obj (+0x29 row cursor,
--     5 rows = 4 moves + close).
--   BATTLE party list = ov198 "b_plist_main.c" (swaps with the battle bag ov197 in the same RAM slot; ov091
--     cannot load during battle - it overlaps ov093). NOT a proc: a GFL task, SAME task list as the battle
--     bag: task fn 0x0220F499, node+0x10 = work. work: +0x2178 state (0x21 = done; 3 = browse, 4 = mon
--     action menu, 5 = detail screen menu), +0x2184 -> shared-list-lib menu (cursor u8 menu+0xD, like
--     b_bag), +0x00 -> battle ctx: +0x1F mode, +0x20 CURSOR (0-5 mons, 6 = Cancel), +0x48+i pick flags.
--     Battle summary/moves are IN-ov198 sub-screens (no ov131 in battle).
--   Party mons are the standard encrypted Gen V structs (0xDC each): blocks seeded by checksum + PID-keyed
--   battle section; decrypted below, CHECKSUM-VALIDATED -> a bad read stays silent (fail closed).
--   BLACK: every anchor ports clean -0x20 (verified research/re/black_party_verify.py: vtable triples, the
--   37-entry b_plist state table, task-fn prologue byte-identical; remaining byte diffs = relative BL
--   immediates from the known ARM9 -0x1c/-0x18 core shift). Struct offsets identical.
local spname_of, mvname_of, mvtype_of, mvmaxpp_of, mvdesc_of, mvstats_of   -- published by the battle move/HP blocks below (load order)
-- ── ITEM NAMES + DESCRIPTIONS (the game's own text, baked offline) ──────────────────────────────────
-- Names = a/0/0/2 bank 54, descriptions = bank 53 — 627 entries each, SAME index, and byte-identical in
-- White and Black (asserted by the generator), so one bake serves both games. Descriptions are generated
-- by research/re/gen_itemdesc.py; the in-game two-line wrapping is flattened to one sentence for speech.
-- ⚠ Do NOT regenerate these with extract_text.to_text(): it is ASCII-only and renders every accented
-- character as "?", which silently turned all 440 "Pokémon" into "Pok?mon" on the first attempt. The
-- generator maps the charcodes itself and reports anything it cannot map instead of emitting a "?".
-- Hoisted to file scope (from inside the party block) so the party screen AND the field bag share one
-- copy. Kept to TWO file-level locals — the blobs stay inside the do block. [lua-syntax-check]
local ITEMS, ITEM_DESC = {}, {}
reg.items = ITEMS        -- registry: the PC box panel is registered above this declaration
reg.item_desc = ITEM_DESC  -- registry: the Poké Mart reader (module 1f2) is registered above it too
