		end
		local function type_words(species)
			local ty, tn = reg.species_types, reg.type_names
			ty = ty and ty[species]
			if not (ty and tn and tn[ty[1]]) then return nil end
			if ty[1] == ty[2] then return tn[ty[1]] end
			return tn[ty[1]] .. ", " .. (tn[ty[2]] or "")
