			if id <= 116 then return LOC[89][id] end
			if id >= 30001 and id <= 30014 then return LOC[92][id - 30001] end
			if id >= 40001 and id <= 40109 then return LOC[90][id - 40001] end
			if id >= 60001 and id <= 60003 then return LOC[91][id - 60001] end
