		-- FUN_021D865E: the IV order is HP, Attack, Defense, Speed, Sp. Atk, Sp. Def; the walk starts at
		-- `PID % 6` and its `bhs` keeps the EARLIER stat on a tie; the entry is 53 + stat*5 + (IV % 5).
		local function charact_line(mon)
			if not mon.ivs then return nil end
			local best, chosen = -1, 0
			for k = 0, 5 do
				local i = (mon.pid % 6 + k) % 6
				local iv = (mon.ivs >> (i * 5)) & 0x1F
				if iv > best then best, chosen = iv, i end
			end
			return CHARACT[chosen * 5 + (best % 5)]
		end
