		-- LOCATION, 5/6/7 egg year/month/day, 8 egg LOCATION. The template prints month/day/20+year
		-- while the struct stores year/month/day — the marking is what keeps the screen's order.
		local function memo_fill(tpl, mon, metloc, eggloc)
			if not tpl or tpl == "" then return nil end
			local v = { [0] = mon.mety, [1] = mon.metm, [2] = mon.metd, [3] = mon.metlv,
			            [4] = loc_name(metloc), [5] = mon.eggy, [6] = mon.eggm, [7] = mon.eggd,
			            [8] = loc_name(eggloc) }
			return (tpl:gsub("{(%d)}", function(n)
				local x = v[tonumber(n)]
				return x ~= nil and tostring(x) or ""
			end))
		end
