				elseif og == 4 or og == 5 then metloc, e = 30004, long       -- Kanto
				elseif og == 7 or og == 8 then metloc, e = 30005, base       -- Johto
				elseif og >= 10 and og <= 12 then metloc, e = 30007, base    -- Sinnoh
				elseif og == 15 then metloc, e = 30008, long                 -- Distant Land
