			[0] = { 3, 1, 2, 6 },
			[1] = { 2, 4, 6 },
			[2] = { 2, 6 },
			[3] = { 3, 1, 6 },
			[4] = { 3, 6 },
			[5] = { 3, 6 },
			[6] = { 0, 6 },
			[7] = { 4, 6 },
			[8] = { 5, 6 },
			[9] = { 4, 6 },
			[10] = { 5, 6 },
			[11] = { 5, 6 },
			[12] = { 0, 6 },
			[13] = { 4, 6 },
			[14] = { 5, 3, 1, 0, 2, 6 },
		},
	},
}
local battle_target_state
do
	local tgt_why
	-- The graph this screen is navigating, selected exactly as the widget's own mode-3 case does
	-- (FUN_02202DE4, 0x02202F9C-0x02202FE8): triple from u32(o+0x50)==2, group from u32(o+0x27C), and the
	-- target type from bits 2..9 of u32(o+0x6C) (`lsls #0x16 ; lsrs #0x18`). All three are widget fields,
	-- which is what makes this readable at all — the graph itself is static ov095 data and is baked above.
	-- The BACK ARROW is a row of the graph like any other (Ola 2026-08-07: "it's the back button that isn't
	-- speaking, because that is also a button apparently"). Its ID is the CANCEL id ov095 compares the
	-- widget's result against right after picking the table: `movs r4,#4` at 0x0689B244 for the four-wide
	-- array and `movs r4,#6` at 0x0689B276 for the six-wide one. No collision is possible — entry indices are
	-- slot-2, so a double has entries 0..3 with cancel 4, and a triple has 0..5 with cancel 6.
	local function tgt_cancel_id(o) return (u32(o + 0x50) == 2) and 6 or 4 end
	local function tgt_graph(o)
		local g = TGT_GRAPH[(u32(o + 0x50) == 2) and 1 or 0]
		g = g and g[u32(o + 0x27C)]
		g = g and g[math.floor(u32(o + 0x6C) / 4) % 256]
		if not g then return nil end
		-- ⛔ RE-CHECK THE SHAPE AT RUNTIME (codex-review 2026-08-07). The generator already refuses to bake
		-- anything that is not a real graph, but the selector (grp / type) is LIVE, so a stale or unexpected
		-- widget state could still land on a legitimate-looking key. These are the same invariants the bake
		-- enforces and they cost a few comparisons: IDs distinct and within range, exactly one cancel, and
		-- the cancel last. A garbage graph must read NOTHING, never a real Pokémon that is not under the
		-- cursor — that was the fail-open this check exists to close.
		local cancel, seen = tgt_cancel_id(o), {}
		for i = 1, #g do
			local id = g[i]
			if id > cancel or seen[id] then return nil end
			if (id == cancel) ~= (i == #g) then return nil end
			seen[id] = true
		end
		return g
	end	battle_target_state = function()
		tgt_why = nil
		if not battle_active() then return nil end
		local o = cmd_widget(3); if not o then return nil end     -- not this screen: no console noise
		local row = cmd_cbits(o)
		-- Both helpers are published by the battle HP block further DOWN the file. They exist by the time
		-- any frame runs, but a nil call would kill the whole loop, so this costs one comparison to make a
		-- future edit that moves either block a silent no-op instead of a crash.
		if not (reg.btl_target_mon and reg.btl_mon_line) then tgt_why = "battle helpers missing"; return nil end
		local graph = tgt_graph(o)
		if not graph then
			tgt_why = string.format("no baked graph for triple=%d grp=%d type=%d",
				(u32(o + 0x50) == 2) and 1 or 0, u32(o + 0x27C), math.floor(u32(o + 0x6C) / 4) % 256)
			return nil
		end
		local id = graph[row + 1]
		if not id then tgt_why = "cursor row " .. row .. " past the graph (" .. #graph .. " rows)"; return nil end
		-- Every row of the graph is a button you can land on, so "X of Y" is simply the row's place in it —
		-- the back arrow included, which is what makes the count match what Ola can actually reach.
		local total, pos = #graph, row + 1
		local live = cmd_shown(o) and cmd_engaged(o) and not cmd_busy(o) and not cmd_confirmed(o)
		if id == tgt_cancel_id(o) then
			-- The one place an English word is unavoidable: this button is a bare return ARROW with no text
			-- source in the ROM, which is exactly the "pre-baked art with no text" exception to reading the
			-- game's own words.
			return row, "Back", total, pos, live
		end
		-- ⛔ DO NOT GATE ON THE 0x25A FLAG HERE. It is redundant: **the GRAPH already is the game's navigable
		-- set** — in Ola's 2v2 its rows are entries 3, 1, 2 and the back arrow, while the attacker's own
		-- blank panel (entry 0) is simply absent from it. So a row that exists is a button you can land on,
		-- full stop. The flag is still read for the console line, because "0 while the row exists" would mean
		-- my reading of what indexes that array is off — worth seeing, but it must not silence a real panel.
		local pp, foe, p, why = reg.btl_target_mon(id)
		if not pp then tgt_why = "row " .. row .. " -> entry " .. id .. ": " .. tostring(why); return nil end
		local body = reg.btl_mon_line(pp, foe)
		if not body then tgt_why = "row " .. row .. " (position " .. p .. "): name unresolved"; return nil end
		return row, (foe and "Enemy " or "Your ") .. body, total, pos, live
	end
	-- ── ONE-PASS INSTRUMENTATION (2026-08-07) ──────────────────────────────────────────────────────────
	-- Three test rounds have now been spent on this screen because a symptom ("that one is quiet", "that one
	-- says enemy") cannot distinguish between the candidate cursor->panel mappings, and every attempt to
	-- settle it by reading alone has run into data the script cannot reach: the button table is handed to the
	-- widget as an argument each frame from a STATIC pool inside ov095, and ov095 is mapped in VRAM.
	-- So stop inferring and record the one thing that decides it. Moving across the panels once now writes a
	-- line per DISTINCT cursor value — the cursor, the game's own selectable flags, and what each on-field
	-- position's slot formula resolves to — which pins the mapping exactly. Console only, never spoken, and
	-- one line per cursor value per screen, so it cannot spam.
	-- One console line the first time this screen is seen: the graph it selected and, per row, the entry ID
	-- and what that resolves to. Console only, never spoken. Kept after the fix because it is the record
	-- that would have settled this in one round instead of four.
	-- ⛔ `local a,b,c = cond and f(x)` KEEPS ONLY THE FIRST RETURN — an `and`/`or` expression is adjusted to
	-- one value in Lua, so b and c come back nil. That is what crashed the reader on Ola's run; guard a
	-- multi-return with a statement, never with `and`.
	local logged = false
	local function target_log(o)
		if logged then return end
		local graph = tgt_graph(o); if not (graph and reg.btl_target_mon) then return end
		logged = true
		local parts = {}
		for i = 1, #graph do
			local id = graph[i]
			local pp, foe, p = reg.btl_target_mon(id)
			parts[#parts + 1] = string.format("row%d->entry%d(flag%d):%s", i - 1, id,
				u8(o + CMD_ENABLED + id),
				(id == tgt_cancel_id(o)) and "BACK"
					or (pp and string.format("pos%d/%s", p, foe and "enemy" or "yours") or "unresolved"))
		end
		dbg(string.format("battle target: triple=%d grp=%d type=%d rows=%d  %s",
			(u32(o + 0x50) == 2) and 1 or 0, u32(o + 0x27C), math.floor(u32(o + 0x6C) / 4) % 256,
			#graph, table.concat(parts, "  ")))
		if reg.btl_slot_map then dbg("battle target: " .. reg.btl_slot_map()) end
	end

	local last, was_readable, last_why, was_msg = nil, false, nil, false
	MODULES[#MODULES + 1] = {
		name = "battle target select",
		-- ⛔ DETECT ON THE SCREEN, NOT ON A SUCCESSFUL READ. If detect required a resolved Pokémon, a panel
		-- that fails to resolve would hand the context to some other module — so the reader would never run,
		-- never log why, and another reader could speak over the target screen. Owning the screen while it is
		-- up is also simply correct: nothing else should be talking here.
		detect = function() return battle_active() and cmd_widget(3) ~= nil end,
		on_enter = function() last, was_readable, logged, was_msg = nil, false, false, false end,
		update = function()
			do local o = cmd_widget(3); if o then target_log(o) end end
			local b, line, total, pos, live = battle_target_state()
			if b == nil then
				-- One console line per DISTINCT reason, never speech. Without this a panel that declines to
				-- read is indistinguishable from a panel that is not there, and telling those two apart has
				-- already cost Ola two test rounds on this screen.
				if tgt_why and tgt_why ~= last_why then dbg("battle target: " .. tgt_why); last_why = tgt_why end
				last, was_readable = nil, false; return
			end
			last_why = nil
			local msg = battle_msg_active()
			local readable = live and not msg
			if readable then
				local landed = not was_readable
				if landed or b ~= last then
					-- ⛔ THE LANDING INTERRUPTS HERE (Ola 2026-08-07: "the button you land on doesn't
					-- interrupt"). The general rule is landing-queues / navigation-interrupts, but that rule
					-- exists to protect a QUEUED SENTENCE the screen itself just posted. Arriving on the
					-- target grid is a SCREEN CHANGE: whatever is still being read is the move you just
					-- picked, and it is stale. ⚠ EXCEPT after a battle MESSAGE (codex-review): a message box
					-- also makes us unreadable, so a message closing looks identical to an arrival — and
					-- interrupting there would cut the game's own sentence off mid-word.
					say(line .. ", " .. pos .. " of " .. total, not was_msg)
				end
			end
			last, was_readable, was_msg = b, readable, msg
		end,
	}
end

-- 4c) BATTLE BAG (ov197 "b_bag_main.c") — ALL THREE of its screens: the CATEGORY grid, the ITEM LIST inside
-- a category, and the USE / CANCEL confirmation a pick opens. Unlike the command/move menus this is NOT
-- btlv_input: it is a SEPARATE overlay loaded when you choose Bag, running as a GFL TASK in the battle task
-- list — so the task's existence IS the open/closed gate and nothing here scans.
--   bagObj = that task's work area: creator FUN_0220c854 registers it via FUN_02030dc0 with task fn
--   0x0220C935 in the battle task manager FUN_021f86f4 (= *(*0x0220AF40)); we iterate the list for that fn
--   (node+0x14 == fn -> node+0x10 = bagObj). The old 1.4 MB tag scan that caused the bag-open lag is gone.
-- ── THE STATE MACHINE, read off the task fn itself (0x0220C934, raw thumb, so the offset is measured) ──
--   0x0220C952  movs r6,#0x53 ; lsls r6,r6,#4      -> 0x530
--   0x0220C956  ldrb r1,[r4,r6] ; cmp r1,#0x14     -> **STATE = u8(bag + 0x530)**, 0x14 = terminal
--   0x0220C95C  lsls r2,r1,#2 ; ldr r1,[pc,#0x3c] ; ldr r1,[r1,r2] ; blx r1 ; strb r0,[r4,r6]
--   i.e. dispatch through the 20-entry handler table at 0x0220DF60 and store the handler's return back as
--   the next state. The three states we read, each confirmed by decompiling its handler:
--     4 = FUN_0220CC38  the CATEGORY grid        5 = FUN_0220CD70  the ITEM LIST
--     6 = FUN_0220D044  the USE / CANCEL confirmation
--   Every screen change parks in state 0x10 (FUN_0220D378: `if u8(bag+0x527) == 0 then goto u8(bag+0x531)`)
--   until the animation byte clears — so simply BEING in state 4/5/6 already means the screen has settled.
-- ⛔ THE GATE IS THE GAME'S OWN (the SUBMENUS hard rule). States 4 and 5 both open with
--   `if (FUN_02021ef4(bag[2]) == 0) { ...read the menu... }` and do nothing otherwise, and FUN_02021ef4
--   decompiles to `(u16(obj+0x118) << 16) >> 18`, i.e. u16 >> 2. So **accepting input ⟺
--   u16( u32(bag+0x08) + 0x118 ) < 4** — a fade counter with two fractional bits. State 6 does NOT check it,
--   so neither do we: following the game exactly, rather than adding a guard that would silence a screen.
-- ── THE ITEM LIST, from the game's own row resolver FUN_0220bbb8 ──────────────────────────────────────
--   `cat = u8(bag+0x533) ; row += s16(ctx + 0x38 + cat*2) * 6 ; id = u16(bag + 0x150 + cat*0x90 + row*4)`
--   and it returns 0 (= not a real row) when that id or the u16 beside it is zero. So:
--     **CATEGORY   = u8(bag + 0x533)**            (state 4 writes the pressed button straight into it)
--     **PAGE       = u16(ctx + 0x38 + cat*2)**, six rows per page (ctx = u32(bag+0), the battle context)
--     **ROW RECORD = bag + 0x150 + cat*0x90 + row*4 = { u16 itemId, u16 quantity }**, 36 rows per category
--   FUN_0220b4d8 (the row DRAW) recomputes the very same `i + page*6`, so the visible index and the cursor
--   index are the same number — the reader and the screen cannot disagree.
-- ⛔ THE COUNT COMES FROM THE GAME, never from walking the array until it stops looking valid. The builder
--   FUN_0220ba4c sweeps bag pockets {0,1,3} (Items / Medicine / Berries — its static list at 0x0220DB5C),
--   tests each item's battle-category bitmask byte (file 0xE8) and appends the record to every category the
--   bits name (bit->category map {2,3,0,1} at 0x0220DB5F), incrementing a per-category counter as it goes:
--     **COUNT    = u8(bag + 0x535 + cat)**
--     **MAX PAGE = u8(bag + 0x539 + cat)** = (count-1)/6, which the scroll handler FUN_0220CFC4 clamps the
--     page against — so page and row are both bounded by fields the game maintains itself.
-- ── WHAT EACH BUTTON IS, from the handlers' switch arms (this is why the old reader was deaf to two of
--   them: it returned nil for any cursor > 3, so Cancel and the last-item shortcut said nothing at all) ──
--   Category grid: 0-3 = the four categories (Ola-confirmed 2x2 column-major mapping), 4 = the LAST-USED
--     ITEM shortcut (`if (s16(bag+0x540) != 0)` -> jumps straight to the confirmation, category taken from
--     u8(bag+0x542); the creator seeds both from the save), 5 = Cancel (identical arm to the B sentinel
--     0xFFFFFFFE: clears ctx+0x16 and leaves).
--   Item list: 0-5 = the six visible rows, 6 = Cancel, 7 = page UP and 8 = page DOWN (they write -1 / +1 to
--     bag+0x534 and hand off to the scroll state 0x0B).
--   Confirmation: 0 = USE (writes the resolved item into ctx+0x16 — this is the press that commits it, and
--     the battle then opens the party list itself if the item needs a target), 1 = Cancel (back to state 8,
--     which re-opens the item list). ctx+0x2a takes the CATEGORY here and 4 in both Cancel arms, so it is
--     an exit/result code, not a row.
-- ✅ THE LABELS ARE THE GAME'S OWN WORDS NOW (Ola 2026-08-07: "we need to speak the games text not our
--   own"). ov197 loads its OWN message bank, and the setup routine says which one outright — raw thumb at
--   0x0220D7B8: `movs r0,#0 ; movs r1,#2 ; movs r2,#0x11 ; blx 0x02045B50 ; str r0,[r5,#0xc]`, i.e.
--   **MsgLoader_New(a/0/0/2, bank 0x11 = 17) -> bag+0x0C**, and two instructions later
--   `lsls r0,r4,#8 (r4=2 -> 0x200) ; blx String_Init ; str r0,[r5,#0x14]` = the 512-char message String at
--   **bag+0x14**, which independently confirms the MSG offset the message reader below already uses.
--   Bank 17 IS this screen's vocabulary, and it decodes to exactly what is on screen:
--     [0]+[1] "HP/PP RESTORE"   [2]+[3] "STATUS RESTORE"   [7] "POKÉ BALLS"   [6] "BATTLE ITEMS"
--     (the first two are two-line buttons, hence the split; [22]-[27] are the same words for the header bar)
--     [8] "LAST USED ITEM"      [31] "USE"      [44]-[51] the six messages FUN_0220D13C fetches — ids
--     0x2C/0x2D/0x2F/0x31/0x32/0x33 = 44/45/47/49/50/51, which is a second, independent confirmation that
--     we had the message path right.
--   The only word left that is ours is "Cancel" for the back arrow, and the two page arrows: those really
--   are pictures (a ↺ and « ») with no string anywhere in the bank.
do
	-- a/0/0/2 bank 17, the bag's own bank (see the header). Baked the same way every other game table in this
	-- file is, so it re-extracts per ROM rather than being English we invented.
	local CATS = { [0] = "HP/PP RESTORE", [1] = "STATUS RESTORE", [2] = "POKÉ BALLS", [3] = "BATTLE ITEMS" }
	local L_LASTITEM, L_USE = "LAST USED ITEM", "USE"          -- bank 17 [8] and [31]
	local BAGFN = 0x0220C935 + DELTA   -- bag GFL task fn (node+0x14); Black 0x0220C915 (ov197, -0x20). node+0x10 = bagObj
	-- ov197 work-area offsets. Every one of these is a STRUCT OFFSET and therefore ports to Black untouched;
	-- the only absolute addresses in this module are BAGFN and the task-manager root.
	local ST, CAT      = 0x530, 0x533        -- state byte / current category
	local CNT0, MAXPG0 = 0x535, 0x539        -- u8[4], one per category
	local LIST0, CSTRIDE, PAGE_ROWS = 0x150, 0x90, 6
	local MENU, FADE   = 0x144, 0x08
	local LASTITEM     = 0x540
	local MSG          = 0x14                -- the String every bag message is fetched into (state 0x0E)
	local function bag_tagged(o)   -- cross-check the "b_ba"... ("b_bag_main.c") tag at obj-0x18
		return inram(o) and inram(o - 0x18) and u8(o-0x18)==0x62 and u8(o-0x18+1)==0x5F and u8(o-0x18+2)==0x62 and u8(o-0x18+3)==0x61
	end
	-- iterate the battle task list (GFL task system: node +0x08 next, +0x10 work, +0x14 fn; mgr head u32(mgr+0x10),
	-- sentinel mgr+8) for the bag task -> bagObj. Try the mgr both deref-depths (robust to the *(*ptr) read).
	local function find_bag_task()
		local mgr = btl_task_mgr(); if not mgr then return nil end
		local sentinel, node, n = mgr + 8, u32(mgr + 0x10), 0
		while inram(node) and node ~= sentinel and n < 64 do
			if u32(node + 0x14) == BAGFN then
				local o = u32(node + 0x10)
				-- LIVENESS: the node is on the battle task manager's LIVE list and its fn is BAGFN, so the bag
				-- task is running; the object comes from that node rather than from a stored handle.
				if bag_tagged(o) then return o end
			end
			node = u32(node + 0x08); n = n + 1
		end
		return nil
	end
	-- The live bag work area, or nil. No heap scan -> no lag.
	-- ⛔ NO TAG-ONLY CACHE (codex-review 2026-08-06, CONFIRMED — and it was MY regression). This used to
	-- keep `bag_obj` and re-accept it on any frame where bag_tagged() still matched. The allocator tag at
	-- obj-0x18 is the heap block's persistent debug info: it SURVIVES the free, so a torn-down bag passes
	-- that check forever. We have now been bitten by exactly this twice — btlv_input's teardown (2026-07-30)
	-- and the PC box menus (2026-08-05, four test rounds, the reader happily reading a menu the game had
	-- already thrown away). It was survivable in the old category-only reader because that also demanded
	-- u8(bag+0x532)==0; it is NOT survivable now, because detect() is "the bag exists" for the whole session,
	-- so one stale object would claim the battle context for the rest of the fight and starve the command,
	-- move and party readers outright.
	-- LIVENESS: membership of the LIVE task list, re-established every frame. The walk IS the validation —
	-- bounded (two managers x 64 nodes, two reads each) and nothing like a heap scan.
	local function bag_work()
		if not battle_active() then return nil end
		return find_bag_task()
	end
	local function cursor(bag)                        -- the shared list library's live highlight
		local m = u32(bag + MENU); if not inram(m) then return nil end
		return u8(m + 0x0D)
	end
	local function input_ready(bag)                   -- the predicate states 4 and 5 test before they read
		local o = u32(bag + FADE); if not inram(o) then return false end
		return u16(o + 0x118) < 4                     -- FUN_02021ef4: (u16 << 16) >> 18 == 0
	end
	-- (itemId, quantity, rowIndex, count) for one row of a category, or nil when the row is not a real one.
	-- Bounds come from the game's own fields, and every failure returns nil rather than a guess.
	local function row_at(bag, cat, vis)
		if cat > 3 or vis > (PAGE_ROWS - 1) then return nil end
		local ctx = u32(bag); if not inram(ctx) then return nil end
		local cnt, maxpg = u8(bag + CNT0 + cat), u8(bag + MAXPG0 + cat)
		local page = u16(ctx + 0x38 + cat * 2)
		if cnt == 0 or page > maxpg then return nil end
		local row = vis + page * PAGE_ROWS
		if row >= cnt then return nil end             -- a blank slot on the last page: stay silent
		-- The builder appends without a cap, so a category holding more than its 0x90/4 = 36 records would
		-- run into the NEXT category's array. That should never happen (36 DISTINCT battle-usable item types
		-- in one pocket), but if it ever does we go silent rather than read a neighbour's item and name it
		-- confidently. Bound comes from the array's own size, not from a guess.
		if row >= (CSTRIDE // 4) then return nil end
		local slot = bag + LIST0 + cat * CSTRIDE + row * 4
		local id, qty = u16(slot), u16(slot + 2)
		if id == 0 or qty == 0 then return nil end    -- exactly FUN_0220bbb8's own validity test
		return id, qty, row, cnt
	end
	-- ⛔ EACH SCREEN SPEAKS WHAT THAT SCREEN SHOWS (Ola's two screenshots, 2026-08-07). This went back and
	-- forth twice, and the screenshots settled it: the item LIST is a grid of name + "x3" tiles with NO
	-- description anywhere, while the CONFIRMATION screen shows the name, the amount AND the full description
	-- above the USE button. So the description belongs on the confirmation, not on every row of the list —
	-- which also answers "it speaks that whole item again": it is not a repeat any more, it is the only place
	-- the game itself says it, and the list got shorter in exchange.
	-- ⛔ NO INVENTED NAMES (codex-review 2026-08-07, CONFIRMED). These used to fall back to "Item 493" when
	-- the baked table had no entry for an id. That is OUR text presented as the game's — the exact thing Ola
	-- ruled out ("we need to speak the games text not our own") — and it would turn a bad read of the record
	-- into confident, authoritative-sounding nonsense rather than the silence a bad read is supposed to give.
	-- A name we cannot source from the game means NO LINE.
	local function row_line(id, qty, row, cnt)        -- the LIST tile: amount, name, position. No description.
		local nm = ITEMS[id]; if not nm or nm == "" then return nil end
		return qty .. " " .. nm .. ", " .. (row + 1) .. " of " .. cnt
	end
	local function detail_line(id, qty)               -- the CONFIRMATION panel: amount, name, description
		local nm = ITEMS[id]; if not nm or nm == "" then return nil end
		local out = { qty .. " " .. nm }
		local d = ITEM_DESC[id]
		if d and d ~= "" then out[#out + 1] = d end
		return table.concat(out, ", ")
	end
	-- The item the CONFIRMATION screen is about. State 6 resolves it as FUN_0220BBB8(bag, s16(ctx+0x30+cat*2))
	-- — the row the item list was left on, saved per category — so we read that same pair. Traced to the use
	-- on BOTH routes in: the list writes that field when you press a row, and the last-used-item shortcut's
	-- setup FUN_0220B9F8 writes it too (row % 6 into +0x30, row / 6 into +0x38, via the divmod FUN_0209C2C8).
	local function confirm_item(bag)
		local ctx = u32(bag); if not inram(ctx) then return nil end
		local cat = u8(bag + CAT)
		if cat > 3 then return nil end
		return row_at(bag, cat, u16(ctx + 0x30 + cat * 2))
	end
	local last_key, last_state, said_panel
	MODULES[#MODULES + 1] = {
		name = "battle bag",
		-- Active for the WHOLE bag session, every screen, so the announcement state survives moving between
		-- them. Speech is gated per state below; a state we cannot read simply says nothing.
		detect = function() return bag_work() ~= nil end,
		on_enter = function() last_key, last_state, said_panel = nil, nil, false end,
		update = function()
			local bag = bag_work()
			if not bag then last_key, last_state, said_panel = nil, nil, false; return end
			local st = u8(bag + ST)
			if st ~= 4 and st ~= 5 and st ~= 6 then
				-- ── STATE 0x0E = THE BAG IS SHOWING A MESSAGE ("You can't use that.", and the five siblings
				-- the ball / trainer-battle checks produce). Worth reading because it is the game's answer to
				-- the button you just pressed, and because this module now claims the whole bag session, so
				-- nothing else would say it. The trigger is the STATE EDGE, not a content diff (the rule the
				-- field bag's shared scratch String taught us), and the edge is exhaustive: xrefs say the
				-- message fetch FUN_02045CC4 has exactly SIX call sites in ov197 (0x0220D15A, D186, D1A4,
				-- D1C2, D1E0, D212), all inside FUN_0220D13C, all passing `param_1[5]` = u32(bag+0x14) as the
				-- destination String, and each one steps to state 0x0E on the same path. So on the frame the
				-- state becomes 0x0E that String holds the message that was just built. reg.str_text fails
				-- closed on magic / length / terminator, so a stale or freed buffer stays silent.
				-- ▶ IT INTERRUPTS, deliberately (codex-review 2026-08-06 flagged this as a queue; REJECTED).
				-- The FIELD bag settled this same question and Ola accepted the answer: a message that is the
				-- game's reply to the button you just pressed cuts off the row you were half-way through,
				-- because it is the newer and more important sentence — and the screen you land on afterwards
				-- then QUEUES behind it (last_key is cleared below, and a fresh screen speaks with entering
				-- == true). Making it queue here would put "You can't use that." AFTER a long item
				-- description you no longer care about.
				-- ⛔ CONSUME THE EDGE ONLY ONCE THE TEXT VALIDATES (codex-review 2026-08-07, CONFIRMED). This
				-- used to move last_state to 0x0E whether or not reg.str_text succeeded, so a single frame
				-- where the String was mid-build silenced that message permanently — there was no second
				-- attempt. Holding the edge costs nothing (the state stays 0x0E while the message is up) and
				-- turns a one-frame timing accident into a one-frame delay.
				if st == 0x0E and last_state ~= 0x0E then
					local t = reg.str_text(u32(bag + MSG))
					if not t then last_key = nil; return end   -- keep the edge; try again next frame
					say(t)
				end
				-- Otherwise: a transition or the teardown. Drop the key so returning to a screen re-announces
				-- what you land on, exactly as leaving a submenu does in the field bag.
				last_key, last_state = nil, st
				return
			end
			if (st == 4 or st == 5) and not input_ready(bag) then return end   -- the game's own gate
			local c = cursor(bag); if not c then return end
			local line, key
			if st == 4 then                               -- ── the category grid
				if c <= 3 then
					line = (CATS[c] or ("Pocket " .. c)) .. ", " .. (c + 1) .. " of 4"
				elseif c == 4 then
					-- The game's own label, plus the item it would use when there is one (the button exists
					-- either way; it simply does nothing until you have used something).
					local it = u16(bag + LASTITEM)
					local nm = (it ~= 0) and ITEMS[it] or nil       -- no invented name; see row_line
					line = L_LASTITEM .. ((nm and nm ~= "") and (", " .. nm) or "")
				elseif c == 5 then
					line = "Cancel"                       -- the ↺ back arrow: a picture, no string in the bank
				end
				key = "c" .. c
			elseif st == 5 then                           -- ── the item list inside a category
				if c <= 5 then
					local id, qty, row, cnt = row_at(bag, u8(bag + CAT), c)
					if id then line = row_line(id, qty, row, cnt) end
				elseif c == 6 then line = "Cancel"
				elseif c == 7 then line = "Previous page"  -- « and » are pictures too
				elseif c == 8 then line = "Next page" end
			else                                          -- ── the USE / CANCEL confirmation
				line = (c == 0) and (L_USE .. ", 1 of 2") or ((c == 1) and "Cancel, 2 of 2" or nil)
			end
			-- An unreadable button (an empty last-item slot, a blank row past the end of a short page, a
			-- cursor value no handler enumerates) says NOTHING — never a guess. It also CLEARS the dedup key,
			-- so moving off a silent button and back onto the one you came from announces it again instead of
			-- being swallowed as "same as last time".
			if not line then last_key = nil; return end
			key = key or (st .. "|" .. line)
			if key == last_key then return end
			local entering = (st ~= last_state)
			-- ⛔ ENTERING A SCREEN INTERRUPTS (Ola 2026-08-07: "when entering submenus ... it needs to interrupt,
			-- now it queues that speech call and that is no no"). Opening a category used to leave the first item
			-- waiting behind the whole "Poké Balls, 3 of 4" you had already heard and acted on. Moving the cursor
			-- interrupted already; now a screen change does too, so the bag never makes you sit through speech you
			-- are finished with. THE ONE EXCEPTION is a screen you land on straight out of the MESSAGE state,
			-- because the game has just answered you there ("You can't use that.") and that sentence must not be
			-- cut off by the row underneath it — and it is the game's own state that tells the two apart, so this
			-- is a distinction we can actually see rather than a guess about timing.
			local after_msg = (last_state == 0x0E)
			-- LANDING ON THE CONFIRMATION reads the panel first — the amount, the name and the DESCRIPTION,
			-- because this screen is the one place the game shows the description (the list is bare tiles).
			-- The panel interrupts, since it answers the button you just pressed, and the USE label queues
			-- behind it so you hear the item and then what you can do about it, in that order.
			-- ⛔ THE PANEL IS DEDUPED SEPARATELY FROM THE BUTTON (codex-review 2026-08-07, CONFIRMED). The
			-- dedup key used to be committed before confirm_item() ran, so a single frame where the saved row
			-- did not resolve lost the item description for good — every later frame hit the dedup and
			-- returned. `said_panel` tracks the panel on its own, so the buttons stay responsive while the
			-- description simply arrives on the first frame it can be read.
			if st == 6 then
				if not said_panel then
					local id, qty = confirm_item(bag)
					local d = id and detail_line(id, qty)
					if d then said_panel = true; say(d); say(line, false); last_key, last_state = key, st; return end
				end
			else
				said_panel = false
			end
			last_key, last_state = key, st
			say(line, not (entering and after_msg))
		end,
	}
end

-- 4d) BATTLE HP READER — query Pokémon HP on demand (NOT a context module: it's a global in-battle handler
-- like the battle text reader, so it works alongside the command/move/bag menus). Keys (battle only):
--   I = your side, O = enemy side ; J = previous, K = current, L = next  (navigate the ON-FIELD Pokémon).
-- Your side reads NUMBERS ("Snivy, level 6, 22 of 22"); the enemy reads a PERCENT ("Lillipup, level 2, 100
-- percent"). Single battle = 1 per side (only K does anything); double/triple = J/K/L walk the on-field mons.
-- NO SCANNING (all Ola-confirmed 2026-06-30): battle server == battle root = u32(u32(0x0220AF40)+0x1E4)
-- (the SAME root battle_scu uses; proven because root+0x10/+0x14 are the btl_clients). pokeparam MANAGER
-- M = root+0xC8 (player perspective). per-CLIENT pokeparam set @ M + 4 + client*0x1c (ptrs at +0,+4..+0x14,
-- COUNT u8 @ +0x18). btl_pokeparam: species u16 @+0x0C, maxHP u16 @+0x0E, curHP u16 @+0x10, level u8 @+0x18.
-- Species names = a/0/0/2 bank 70 (research/re/species_names_gen.lua.txt). STATUS not read yet (offset TBD).
--
-- ⛔ v2 (2026-08-07) — DOUBLE BATTLES SPOKE ONLY ONE MON PER SIDE. Ola in a 2v2 (Servine + Woobat vs two
-- Sewaddle) heard exactly one Pokémon on each side. Root cause, from ov093 raw thumb: **btl_adapter is
-- indexed by CLIENT ID, not by battle position.** BtlClient_Create (0x021CD710) takes the client id in r7,
-- stores it at client+0x1A6, and passes that SAME value as the array index to the adapter getter
-- (0x021EEA78: `if (arr[param_2*4] == 0) alloc(0xbd0)`, and it writes param_2 to adapter+0x0D). A normal
-- battle — single OR double — has exactly TWO clients, so the old `#adapters / 2` was 1 every time and only
-- looked right on singles. The whole adapter count, its tag check and the absolute 0x021F63A8 are DELETED.
--
-- ✅ THE REAL SOURCE — the engine's own position table, a pure STRUCT OFFSET on the root we already hold:
--     **posClient(p) = u8(root + 0x428 + p)** for p = 0..5 — which CLIENT owns battle position p; **4 = empty**.
--   Proven end to end in ov093:
--     • 0x021B66F4 fills all six bytes with **4** first (`movs r5,#4 ; strb r5,[r4,r3] ; cmp r6,#6 ; blo`),
--       so an unused position can never be mistaken for client 0 — that is what makes counting safe.
--     • It then dispatches on the rule to a per-rule setter, each writing the table off the literal 0x46B/0x46C:
--         rule 0 SINGLE   (0x021B6ACC): [0x428]=0 [0x429]=1                       -> 1 per side
--         rule 1 DOUBLE   (0x021B6C7C): [0x428]=0 [0x429]=1 [0x42A]=0 [0x42B]=1   -> 2 per side  ← Ola's battle
--         rule 1 MULTI    (0x021B6DF0): same default, then [0x42A]=2 [0x42B]=3 for a real multi
--         rule 2 TRIPLE   (0x021B7070): [0x428..0x42D] = 0,1,0,1,0,1              -> 3 per side
--         rule 3 ROTATION (0x021B71F4): same shape
--     • **Those same functions build the pokecon we already read: `adds r0,r5,#0xC8 ; bl 0x21B9400`, with r5
--       the very register they just wrote +0x428 through.** So the object carrying the position table IS the
--       object whose +0xC8 this reader has been reading correctly in-game since June — the chain is verified
--       at the point of use, not inherited.
--     • The engine counts on-field mons exactly this way: 0x021B8B98 = "how many of the six bytes equal this
--       client", and 0x021B9D30 calls it and then treats set member[thatCount] as the first BENCHED mon —
--       i.e. members [0 .. count-1] are the ones out. 0x021B8C0C is the inverse (client-slot n -> position).
--     • SWITCHING keeps that true: the switch handler 0x021BD45C resolves both slots with 0x021B8C0C and then
--       calls **0x021B9C30 = swap(set, i, j)** on the per-client set, so the mon that comes out is swapped
--       INTO the front slot. Member index n of a client is always its n-th battle position.
--     • Player's own client = **u8(root + 0x46C)** (written from setupParam+0x21 at 0x021B6876), so "your
--       side" is derived, not assumed. Side of a client = client & 1 (monID bases u8[0x021EFD10+c] are
--       {0,12,6,18}, and 0x021B9A60 splits sides at monID 12 -> clients 0,2 = your side; 1,3 = theirs).
-- ▶ NO new absolute address — every hop added here is a struct offset on the existing root, so Black rides
--   the same 0x0220AF40+DELTA anchor for free, and the port loses one absolute (0x021F63A8) rather than
--   gaining any.
-- ▶ STATUS: ✅ Ola-CONFIRMED on WHITE in a real 2v2 (both Pokémon listed per side). ⏳ BLACK UNTESTED, and
--   so are triple / rotation / multi battles — the layouts for those are read out of the ROM and are only
--   EXPECTED to work. A wrong read fails CLOSED: the shape check rejects the position table, a failed slot
--   invalidates the whole roster rather than shortening it, and every rejection prints a console reason.
--   Diagnostic if it misreads: scripts/battle-pos-probe.lua, press N.
local battle_hp_step
do
	local NAMES = ",Bulbasaur,Ivysaur,Venusaur,Charmander,Charmeleon,Charizard,Squirtle,Wartortle,Blastoise,Caterpie,Metapod,Butterfree,Weedle,Kakuna,Beedrill,Pidgey,Pidgeotto,Pidgeot,Rattata,Raticate,Spearow,Fearow,Ekans,Arbok,Pikachu,Raichu,Sandshrew,Sandslash,Nidoran female,Nidorina,Nidoqueen,Nidoran male,Nidorino,Nidoking,Clefairy,Clefable,Vulpix,Ninetales,Jigglypuff,Wigglytuff,Zubat,Golbat,Oddish,Gloom,Vileplume,Paras,Parasect,Venonat,Venomoth,Diglett,Dugtrio,Meowth,Persian,Psyduck,Golduck,Mankey,Primeape,Growlithe,Arcanine,Poliwag,Poliwhirl,Poliwrath,Abra,Kadabra,Alakazam,Machop,Machoke,Machamp,Bellsprout,Weepinbell,Victreebel,Tentacool,Tentacruel,Geodude,Graveler,Golem,Ponyta,Rapidash,Slowpoke,Slowbro,Magnemite,Magneton,Farfetch'd,Doduo,Dodrio,Seel,Dewgong,Grimer,Muk,Shellder,Cloyster,Gastly,Haunter,Gengar,Onix,Drowzee,Hypno,Krabby,Kingler,Voltorb,Electrode,Exeggcute,Exeggutor,Cubone,Marowak,Hitmonlee,Hitmonchan,Lickitung,Koffing,Weezing,Rhyhorn,Rhydon,Chansey,Tangela,Kangaskhan,Horsea,Seadra,Goldeen,Seaking,Staryu,Starmie,Mr. Mime,Scyther,Jynx,Electabuzz,Magmar,Pinsir,Tauros,Magikarp,Gyarados,Lapras,Ditto,Eevee,Vaporeon,Jolteon,Flareon,Porygon,Omanyte,Omastar,Kabuto,Kabutops,Aerodactyl,Snorlax,Articuno,Zapdos,Moltres,Dratini,Dragonair,Dragonite,Mewtwo,Mew,Chikorita,Bayleef,Meganium,Cyndaquil,Quilava,Typhlosion,Totodile,Croconaw,Feraligatr,Sentret,Furret,Hoothoot,Noctowl,Ledyba,Ledian,Spinarak,Ariados,Crobat,Chinchou,Lanturn,Pichu,Cleffa,Igglybuff,Togepi,Togetic,Natu,Xatu,Mareep,Flaaffy,Ampharos,Bellossom,Marill,Azumarill,Sudowoodo,Politoed,Hoppip,Skiploom,Jumpluff,Aipom,Sunkern,Sunflora,Yanma,Wooper,Quagsire,Espeon,Umbreon,Murkrow,Slowking,Misdreavus,Unown,Wobbuffet,Girafarig,Pineco,Forretress,Dunsparce,Gligar,Steelix,Snubbull,Granbull,Qwilfish,Scizor,Shuckle,Heracross,Sneasel,Teddiursa,Ursaring,Slugma,Magcargo,Swinub,Piloswine,Corsola,Remoraid,Octillery,Delibird,Mantine,Skarmory,Houndour,Houndoom,Kingdra,Phanpy,Donphan,Porygon2,Stantler,Smeargle,Tyrogue,Hitmon